content:
@charset "UTF-8";
/* Variable overrides — pure white base for Swiss/Brutalist aesthetic */
/* Banner height — compact title block (was 640px) */
/**
 * Reset some basic elements
 */
body, h1, h2, h3, h4, h5, h6,
p, blockquote, pre, hr,
dl, dd, ol, ul, figure {
  margin: 0;
  padding: 0;
}

/**
 * Basic styling
 */
body {
  font-family: "GenSekiGothic2", sans-serif;
  font-weight: 400;
  font-size: 14px;
  font-display: swap;
  line-height: 1.6;
  color: #3E3F40;
  background-color: #ffffff;
  -webkit-text-size-adjust: 100%;
  -webkit-font-feature-settings: "kern" 1;
  -moz-font-feature-settings: "kern" 1;
  -o-font-feature-settings: "kern" 1;
  font-feature-settings: "kern" 1;
  font-kerning: normal;
  display: flex;
  min-height: 100vh;
  flex-direction: column;
  transition-duration: 0.3s;
}

html[lang=ja] body {
  font-family: "Zen Maru Gothic Medium", sans-serif !important;
}

/**
 * Set `margin-bottom` to maintain vertical rhythm
 */
h1, h2, h3, h4, h5, h6,
p, blockquote, pre,
ul, ol, dl, figure {
  margin-bottom: 15px;
}

/**
 * `main` element
 */
main {
  display: block; /* Default value of `display` of `main` element is 'inline' in IE 11. */
}

/**
 * Images
 */
img {
  max-width: 100%;
  vertical-align: middle;
}

/**
 * Figures
 */
figure > img {
  display: block;
}

figcaption {
  font-size: 12.25px;
}

/**
 * Lists
 */
ul, ol {
  margin-left: 30px;
}

li > ul,
li > ol {
  margin-bottom: 0;
}

/**
 * Headings
 */
h1, h2, h3, h4, h5, h6 {
  font-weight: 400;
}

/**
 * Links
 */
a {
  color: #0000FF;
  text-decoration: none;
}
a:hover {
  text-decoration: underline;
}
.social-media-list a:hover {
  text-decoration: none;
}
.social-media-list a:hover .username {
  text-decoration: underline;
}

/**
 * Blockquotes
 */
blockquote {
  color: #3E3F40;
  border-left: 4px solid #dddddd;
  padding-left: 15px;
  font-size: 15.75px;
  letter-spacing: -1px;
}
blockquote > :last-child {
  margin-bottom: 0;
}

/**
 * Code formatting
 */
pre,
code {
  font-size: 13.125px;
  color: #3E3F40;
}

*:not(pre) > code {
  padding: 3px 6px;
  border-radius: 3px;
  background-color: #000000;
  margin: 0 5px;
}

pre {
  overflow-x: auto;
  position: relative;
  background-color: #f0f0f0;
}
pre > code {
  display: inline-block;
  padding: 20px !important;
  background-color: transparent;
  border: 0;
}
pre table, pre pre {
  margin-bottom: 0;
}
pre table .gutter, pre table .code, pre pre .gutter, pre pre .code {
  padding: 6px;
  border: none;
}

/**
 * Wrapper
 */
.wrapper {
  max-width: 1000px;
  margin: auto;
  padding-right: 30px;
  padding-left: 30px;
}

/**
 * Clearfix
 */
.wrapper:after {
  content: "";
  display: table;
  clear: both;
}

/**
 * Tables
 */
table {
  display: block;
  margin-bottom: 30px;
  width: 100%;
  text-align: left;
  color: #4b4c4d;
  border-collapse: collapse;
  overflow: auto;
}
table tr:nth-child(even) {
  background-color: #ececec;
}
table th, table td {
  padding: 10px 15px;
}
table th {
  background-color: #e5e5e5;
  border: 1px solid lightgray;
  border-bottom-color: #bebebe;
}
table td {
  border: 1px solid #dddddd;
}

/**
 * Flex layout
 */
.framework {
  display: flex;
}

.framework .main, .page-content {
  flex: 1;
  min-width: 0; /*  svg {
    fill: #fdfdfd;
  }
}
html[data-scroll-status=top] footer.site-footer {
  color: unset;
  background-color: transparent;
}
html[data-scroll-status=top] footer.site-footer .site-footer-inner {
  border-top: solid 1px #eee;
}
html[data-scroll-status=down] header.site-header {
  top: -63.84px;
}
html[data-scroll-status=down] .framework .sidebar {
  top: 20px;
}

/**
 * Site header
 */
.site-header {
  background-color: #ffffff;
  height: 63.84px;
  width: 100%;
  transition: height 0.2s, text-shadow 0.2s, top 0.2s;
  box-shadow: 0 1px 0 0 rgba(0, 0, 0, 0.06);
  position: sticky;
  position: -moz-sticky; /*  .wrapper {
  margin: 0 60px;
  padding: 0;
  max-width: 100%;
  transition: 0.2s margin;
}
@media screen and (max-width: 1024px) {
  .site-header > .wrapper {
    margin: 0 20px;
    max-width: unset;
  }
}
.site-header a {
  text-decoration: none;
}
.site-header .site-header-inner {
  position: relative;
}

.site-brand {
  line-height: 63.84px;
  margin-right: 50px;
}
.site-brand .site-brand-inner {
  font-size: 15.75px;
  font-weight: 400;
  letter-spacing: -1px;
  transition: 0.1s filter color;
  font-family: "jfhuninn", sans-serif;
}
.site-brand .site-brand-inner, .site-brand .site-brand-inner:visited {
  color: black;
}
.site-brand .site-brand-inner .site-favicon {
  display: inline-block;
  height: 42.56px;
  margin-right: 5px;
}

.site-nav {
  font-size: 17.5px;
  line-height: 63.84px;
  position: absolute;
  right: 0;
  top: 0;
}
.site-nav .nav-trigger {
  display: none;
}
.site-nav .menu-icon {
  display: none;
}
.site-nav .page-link {
  line-height: 1.6;
  color: black;
  transition: 0.1s ease-in-out;
  font-family: "jfhuninn", sans-serif;
  font-weight: 400;
}
.site-nav .page-link:not(:last-child) {
  margin-right: 24px;
}
.site-nav .page-link:not(:last-child):hover {
  text-decoration: underline;
}
@media screen and (max-width: 800px) {
  .site-nav {
    position: absolute;
    top: 0;
    text-align: left;
  }
  .site-nav label[for=nav-trigger] {
    display: block;
    z-index: 2;
    cursor: pointer;
  }
  .site-nav .menu-icon {
    display: block;
    float: right;
    text-align: center;
  }
  .site-nav .menu-icon > svg {
    fill: rgba(0, 0, 0, 0.8);
    transition: 0.1s fill;
  }
  .site-nav input ~ .trigger {
    clear: both;
    display: none;
    border-radius: 3px;
    box-shadow: 1px 1px 1px 1px rgba(0, 0, 0, 0.06);
  }
  .site-nav input:checked ~ .trigger {
    display: block;
    background: #ffffff;
  }
  .site-nav .page-link {
    display: block;
    padding: 5px 10px;
    color: rgba(0, 0, 0, 0.8);
    margin: 0 25px;
  }
}

/**
 * Site footer
 */
.site-footer {
  font-size: 14px;
  color: #404040;
  background-color: #f2f2f2;
  text-align: left;
  transition: background-color 0.2s;
}
.site-footer .site-footer-inner {
  transition: border-top 0.2s;
  padding: 54px 0;
}
.site-footer a {
  color: #0000FF;
}
.site-footer a:hover {
  color: #3333ff;
}

.copyleft {
  display: inline-block;
  transform: rotate(180deg);
}

/**
 * Post header
 */
.post .post-header {
  margin-bottom: 30px;
}
.post .post-title {
  font-size: 42px;
  letter-spacing: -1px;
  line-height: 1;
}
@media screen and (max-width: 800px) {
  .post .post-title {
    font-size: 35px;
  }
}
.post .post-tags {
  padding-right: 150px;
}
.post .post-tags .post-tag {
  display: inline-block;
  margin: 0 12px 0 0;
}

/**
 * Page content
 */
.page-content {
  /*  li {
  margin-bottom: 45px;
  padding-bottom: 30px;
}
.pagination .post-list > li:not(:last-child) {
  border-bottom: 1px solid #e3e3e3;
}
.pagination .post-title {
  margin-bottom: 6px;
  transition: 0.2s all;
}
.pagination .post-title a {
  text-decoration: none;
}
.pagination .post-link {
  font-size: 23.1px;
  font-weight: 400;
  color: #333;
}
.pagination .post-meta {
  color: #3E3F40;
  font-size: 14px;
  margin-bottom: 15px;
}
.pagination .post-excerpt {
  display: flex;
  position: relative;
  gap: 15px;
  margin-bottom: 15px;
}
.pagination .post-excerpt .post-image > *:first-child {
  flex: 0 1 38.2%;
  width: 100%;
  height: 100%;
  background-size: cover;
  background-position: center center;
  overflow: hidden;
  transition: 0.2s all ease-in-out;
}
.pagination .post-list.none-image-style .post-item .post-excerpt .post-image {
  display: none;
}
.pagination .post-list.left-image-style .post-item .post-excerpt {
  flex-direction: row;
}
.pagination .post-list.right-image-style .post-item .post-excerpt {
  flex-direction: row-reverse;
}
.pagination .post-list.post-list.top-image-style .post-item .post-excerpt {
  flex-direction: column;
}
.pagination .post-list.z-image-style .post-item:nth-child(even) .post-excerpt {
  flex-direction: row-reverse;
}
.pagination .post-list.z-reverse-image-style .post-item:nth-child(odd) .post-excerpt {
  flex-direction: row-reverse;
}
@media screen and (max-width: 800px) {
  .pagination .post-list .post-item .post-excerpt {
    flex-direction: column !important;
  }
}
.pagination .post-text {
  color: #3E3F40;
  word-break: break-word;
  overflow-wrap: break-word;
  flex: 1;
}
.pagination .post-tags .post-tag {
  display: inline-block;
  text-decoration: none;
  border: 1px solid;
  padding: 2px 4px;
  border-radius: 2px;
  transition: color 0.2s;
  margin-bottom: 8px;
}
.pagination .post-tags .post-tag:not(:last-child) {
  margin-right: 8px;
}
.pagination .post-tags .post-tag:hover {
  color: #787878;
}
.pagination .paginator {
  text-align: center;
}
.pagination .paginator > .previous:before {
  content: " ";
  border: solid #787878;
  border-width: 0 2px 2px 0;
  display: inline-block;
  padding: 4px;
  margin-right: 8px;
  transform: rotate(135deg);
  -webkit-transform: rotate(135deg);
}
.pagination .paginator > .next:after {
  content: " ";
  border: solid #787878;
  border-width: 0 2px 2px 0;
  display: inline-block;
  padding: 4px;
  margin-left: 8px;
  transform: rotate(-45deg);
  -webkit-transform: rotate(-45deg);
}
.pagination .paginator .previous span, .pagination .paginator .next span {
  color: #b3b3b3;
}
.pagination .paginator .indicator {
  padding: 0 15px;
}

/**
 * Posts
 */
.post .post-header {
  margin: 50px auto 60px;
  padding: 0 0 20px;
}
.post .post-header .post-title {
  margin-bottom: 6px;
}
.post .post-header .post-subtitle {
  font-weight: 400;
  font-size: 21px;
}
.post .post-header .post-meta {
  color: #3E3F40;
  padding-bottom: 15px;
}
.post .post-content {
  margin-bottom: 30px;
  overflow-wrap: normal;
  word-wrap: normal;
  word-break: normal;
  /* ---------- Headings ---------- */
  /* ---------- Media ---------- */
  /* ---------- Paragraph & Horizontal rule ---------- */
}
.post .post-content h1 {
  /* 約 36 px；在小螢幕縮到 28 px 左右 */
  font-size: 31.5px;
  line-height: 1.25;
  margin: 72px 0 24px;
}
@media screen and (max-width: 800px) {
  .post .post-content h1 {
    font-size: 24.5px;
  }
}
.post .post-content h2 {
  font-size: 30.8px;
  margin: 60px 0 19px;
}
@media screen and (max-width: 800px) {
  .post .post-content h2 {
    font-size: 26.6px;
  }
}
.post .post-content h3 {
  font-size: 25.2px;
  margin: 60px 0 19px;
}
@media screen and (max-width: 800px) {
  .post .post-content h3 {
    font-size: 21px;
  }
}
.post .post-content h4 {
  font-size: 19.6px;
  margin: 60px 0 19px;
}
@media screen and (max-width: 800px) {
  .post .post-content h4 {
    font-size: 16.8px;
  }
}
.post .post-content h5 {
  font-size: 15.4px;
  margin: 60px 0 19px;
}
@media screen and (max-width: 800px) {
  .post .post-content h5 {
    font-size: 14px;
  }
}
.post .post-content h6 {
  font-size: 12.6px;
  margin: 60px 0 19px;
}
@media screen and (max-width: 800px) {
  .post .post-content h6 {
    font-size: 11.2px;
  }
}
.post .post-content img,
.post .post-content svg,
.post .post-content iframe {
  margin-left: auto;
  margin-right: auto;
}
.post .post-content img:not(.emoji),
.post .post-content svg,
.post .post-content iframe {
  display: block;
  max-height: 50vh;
}
.post .post-content hr {
  height: 1px;
  background-color: #ebebeb;
  border: none;
  margin: 60px 0;
}
.post .post-content img, .post .post-content svg, .post .post-content iframe {
  margin-left: auto;
  margin-right: auto;
}
.post .post-content img:not(.emoji), .post .post-content svg, .post .post-content iframe {
  display: block;
  max-height: 50vh;
}
.post .post-related > *:first-child {
  font-size: 19.95px;
  color: #3E3F40;
  margin-bottom: 14px;
}
.post .post-related ul {
  margin-left: 15px;
}
.post .post-related .post-link {
  font-size: 15.05px;
  color: #3E3F40;
}
.post .post-related .post-link:hover {
  color: black;
}

.post-comments {
  padding-top: 25px;
}

/**
 * Posts misc
 */
.post-nav {
  display: flex;
  justify-content: space-between;
  margin: 72px 0 59px;
  padding: 31px 0 0;
  gap: 36px;
}
.post-nav a {
  font-size: 15.75px;
  color: #3E3F40;
  max-width: 45%;
  display: flex;
  align-items: center;
}
.post-nav a * {
  overflow: hidden;
  text-wrap-mode: nowrap;
  text-overflow: ellipsis;
}
.post-nav .previous:before {
  content: " ";
  border: solid #787878;
  border-width: 0 2px 2px 0;
  display: inline-block;
  padding: 4px;
  margin-right: 8px;
  transform: rotate(135deg);
  -webkit-transform: rotate(135deg);
}
.post-nav .next:after {
  content: " ";
  border: solid #787878;
  border-width: 0 2px 2px 0;
  display: inline-block;
  padding: 4px;
  margin-left: 8px;
  transform: rotate(-45deg);
  -webkit-transform: rotate(-45deg);
}

/**
 * Archives page
 */
.page-archives .page-archives-list {
  margin-left: 0;
  list-style: none;
}
.page-archives .archives-time {
  font-size: 21px;
  margin-bottom: 8px;
}
.page-archives .archives-time:not(:first-child) {
  margin-top: 18px;
}
.page-archives .post-meta {
  font-size: 12.25px;
  color: #777;
}

/**
 * Page banner
 */
.page-banner {
  display: block;
  position: relative;
  height: 260px;
  background-color: rgba(0, 0, 0, 0.8);
  transition: height 0.2s;
}
.page-banner .page-banner-img {
  position: absolute;
  width: 100%;
  height: 100%;
  overflow: hidden;
}
.page-banner .page-banner-img > *:first-child {
  height: 100%;
  max-width: 1000%;
  background-size: cover;
  background-position: center center;
  overflow: hidden;
  transition: 0.1s all ease-in-out;
}
.page-banner .page-banner-img > video {
  width: 100vw;
  object-fit: cover;
}
.page-banner .page-banner-img > img.img-placeholder {
  display: none;
}
.page-banner .wrapper {
  height: 100%;
}
.page-banner .page-banner-inner {
  position: relative;
  top: 50%;
  transform: translateY(-50%);
  color: #fdfdfd;
  padding: 10px 5px;
  text-shadow: 1px 1px 2px rgba(51, 51, 51, 0.3333333333);
}
.page-banner .page-banner-inner > *:first-child {
  margin: 0;
}
.page-banner .page-banner-inner > *:first-child > :nth-child(1) {
  font-size: 54.6px;
  letter-spacing: -1px;
  margin-bottom: 0.1em;
  font-weight: normal;
  transition: 0.2s all;
}
@media screen and (max-width: 600px) {
  .page-banner .page-banner-inner > *:first-child > :nth-child(1) {
    font-size: 27.65px;
  }
}
.page-banner .page-banner-inner > *:first-child > :nth-child(2) {
  font-weight: lighter;
  margin-bottom: 0.8em;
  transition: 0.2s all;
}
@media screen and (max-width: 600px) {
  .page-banner .page-banner-inner > *:first-child > :nth-child(2) {
    font-size: 16.45px;
  }
}
.page-banner .page-banner-inner > *:first-child > :last-child {
  margin-bottom: 0;
}
.page-banner .page-banner-inner .post-subtitle {
  font-size: 21.35px;
  color: rgba(255, 255, 255, 0.8);
  padding-right: 280px;
}
@media screen and (max-width: 600px) {
  .page-banner .page-banner-inner .post-subtitle {
    padding-right: 0;
  }
}
.page-banner .page-banner-inner .post-meta {
  color: rgba(255, 255, 255, 0.8);
  padding-bottom: 1em;
}
.page-banner .page-banner-inner .left-vsplit:before {
  background: rgba(227, 227, 227, 0.5333333333);
}
.page-banner .page-banner-inner .post-tags {
  color: #999;
  padding-right: 280px;
}
@media screen and (max-width: 600px) {
  .page-banner .page-banner-inner .post-tags {
    padding-right: 0;
  }
}
.page-banner .page-banner-inner .post-tags .post-tag {
  font-size: 15.75px;
  display: inline-block;
  text-decoration: none;
  margin: 9px 12px 0 0;
  color: #fff;
}
.page-banner .page-banner-inner .post-tags .post-tag:hover {
  text-decoration: underline;
}
@media screen and (max-width: 600px) {
  .page-banner {
    height: 173.3333333333px;
  }
}

/**
 * Layout and sidebar
 */
.framework .sidebar {
  padding-left: 8px;
  transition: top 0.2s, display 0.2s;
  position: sticky;
  position: -moz-sticky; /*  code {
  color: #b0b0b0;
  background-color: #454545;
}
html[data-theme=dark] blockquote {
  border-left: 4px solid #484848;
}
html[data-theme=dark] table {
  color: #9d9d9d;
}
html[data-theme=dark] table th {
  background-color: #050505;
}
html[data-theme=dark] table tr:nth-child(even) {
  background-color: #080808;
}
html[data-theme=dark] .site-header {
  background-color: #090909;
}
html[data-theme=dark] .site-header .site-brand .site-brand-inner, html[data-theme=dark] .site-header .site-brand .site-brand-inner:visited {
  color: #f8f8f8;
}
html[data-theme=dark] .site-header .site-nav .page-link {
  color: #f8f8f8;
}
html[data-theme=dark] .site-header .ct-language-dropdown {
  color: #f8f8f8;
  background-color: #0e0e0e;
  box-shadow: 0 0 3px 1px rgba(0, 0, 0, 0.3568627451);
}
html[data-theme=dark] .site-header .ct-language-selected, .ct-language-dropdown html[data-theme=dark] .site-header li:hover, html[data-theme=dark] .site-header .ct-language-dropdown li:hover {
  background-color: #222 !important;
}
@media screen and (max-width: 800px) {
  html[data-theme=dark] .site-header .menu-icon > svg {
    fill: rgba(176, 176, 176, 0.8);
  }
  html[data-theme=dark] .site-header .site-nav input:checked ~ .trigger {
    background-color: #090909;
  }
}
html[data-theme=dark] .site-footer {
  color: #fff;
  background-color: #000;
}
html[data-theme=dark] .left-vsplit:before {
  background-color: #505050;
}
html[data-theme=dark] .page-banner .page-banner-img > *:first-child {
  opacity: 0.718;
}
html[data-theme=dark] .pagination .post-link {
  color: #bbb;
}
html[data-theme=dark] .pagination .post-excerpt {
  color: #3E3F40;
}
html[data-theme=dark] .pagination .post-list > li:not(:last-child) {
  border-bottom: 1px solid #545454;
}
html[data-theme=dark] .pagination .post-tags .post-tag:hover {
  color: #d7d7d7;
}
html[data-theme=dark] .page-segments li a {
  color: #ddd;
}
html[data-theme=dark] .post .post-header {
  border-bottom: 1px solid #555;
}
html[data-theme=dark] .post .post-content img:not(.emoji):not([raw]) {
  background-color: rgba(255, 255, 255, 0.2);
}
html[data-theme=dark] .post .post-content hr {
  background-color: #555;
}
html[data-theme=dark] .post .post-related > *:first-child {
  color: #d7d7d7;
}
html[data-theme=dark] .post .post-related a:hover {
  color: #aaa;
}
html[data-theme=dark] .common-list li {
  border-bottom: solid 1px rgba(64, 64, 64, 0.5333333333);
