/* ==========================================================================
   Swiss Typography / Web Brutalism Design System
   Aesthetic reference: Aaron Nieh Workshop
   Load order: this file is last — all rules here beat Yat theme defaults.
   ========================================================================== */
/* ─── 1. Custom properties ─────────────────────────────────────────────── */
:root {
  --white: #FFFFFF;
  --black: #111111;
  --accent: #0000FF;
  /* Hover & selection: light blue */
  --hover-bg: #DBEAFE;
  /* light blue background */
  --hover-text: #1e3a5f;
  /* dark navy for readable contrast on hover */
  /* Search overlay sizing */
  --search-width: min(720px, 96vw);
  --search-input-font: clamp(1.0rem, 0.9rem + 0.5vw, 1.15rem);
  --search-title-font: clamp(0.95rem, 0.85rem + 0.4vw, 1.1rem);
  --search-snippet-font: clamp(0.85rem, 0.8rem + 0.3vw, 0.95rem);
}

/* ─── Text selection: blue highlight ────────────────────────────────────── */
::selection {
  background-color: var(--hover-bg);
  color: var(--hover-text);
}

::-moz-selection {
  background-color: var(--hover-bg);
  color: var(--hover-text);
}

/* ─── 2. Global hard resets ─────────────────────────────────────────────── */
*,
*::before,
*::after {
  border-radius: 0 !important;
  box-shadow: none !important;
}

/* Instant interactions — no transitions */
a,
button,
input,
.menu-wrapper,
.menu-toggle span {
  transition: none !important;
}

/* ─── 3. Base ────────────────────────────────────────────────────────────── */
body {
  background-color: var(--white) !important;
  color: var(--black) !important;
  /* Inter handles Latin; Blix (卜力士) handles CJK body text */
  font-family: "Inter", "Helvetica Neue", Helvetica, Arial, "Segoe UI", "Blix", "IBM Plex Sans TC", "PingFang TC", "Microsoft JhengHei", sans-serif;
  font-size: 1rem;
  line-height: 1.7;
  font-weight: 500;
  /* Blix-Medium for comfortable CJK reading weight */
}

/* Japanese — Blix first, then Zen Maru */
html[lang=ja] body {
  font-family: "Inter", "Helvetica Neue", "Blix", "Zen Maru Gothic Medium", sans-serif !important;
}

/* ─── 4. Local font faces ────────────────────────────────────────────────── */
/* Satoshi - used for Latin text in banner headings */
@font-face {
  font-family: "Satoshi";
  src: url("/assets/css/fonts/Satoshi-Variable.ttf") format("truetype");
  font-weight: 300 900;
  font-style: normal;
  font-display: swap;
}
/* GenSekiGothicTW (源石黑體) — 3 weights, used for CJK headings */
@font-face {
  font-family: "GenSekiGothicTW";
  src: url("/assets/css/fonts/GenSekiGothic2TW-R.otf") format("opentype");
  font-weight: 400;
  font-style: normal;
  font-display: swap;
}
@font-face {
  font-family: "GenSekiGothicTW";
  src: url("/assets/css/fonts/GenSekiGothic2TW-M.otf") format("opentype");
  font-weight: 500;
  font-style: normal;
  font-display: swap;
}
@font-face {
  font-family: "GenSekiGothicTW";
  src: url("/assets/css/fonts/GenSekiGothic2TW-B.otf") format("opentype");
  font-weight: 700;
  font-style: normal;
  font-display: swap;
}
/* Blix (卜力士) — 8 weights, used for CJK body text */
@font-face {
  font-family: "Blix";
  src: url("/assets/css/fonts/Blix-Thin.otf") format("opentype");
  font-weight: 100;
  font-style: normal;
  font-display: swap;
}
@font-face {
  font-family: "Blix";
  src: url("/assets/css/fonts/Blix-ExtraLight.otf") format("opentype");
  font-weight: 200;
  font-style: normal;
  font-display: swap;
}
@font-face {
  font-family: "Blix";
  src: url("/assets/css/fonts/Blix-Light.otf") format("opentype");
  font-weight: 300;
  font-style: normal;
  font-display: swap;
}
@font-face {
  font-family: "Blix";
  src: url("/assets/css/fonts/Blix-Regular.otf") format("opentype");
  font-weight: 400;
  font-style: normal;
  font-display: swap;
}
@font-face {
  font-family: "Blix";
  src: url("/assets/css/fonts/Blix-Text.otf") format("opentype");
  font-weight: 450;
  font-style: normal;
  font-display: swap;
}
@font-face {
  font-family: "Blix";
  src: url("/assets/css/fonts/Blix-Medium.otf") format("opentype");
  font-weight: 500;
  font-style: normal;
  font-display: swap;
}
@font-face {
  font-family: "Blix";
  src: url("/assets/css/fonts/Blix-SemiBold.otf") format("opentype");
  font-weight: 600;
  font-style: normal;
  font-display: swap;
}
@font-face {
  font-family: "Blix";
  src: url("/assets/css/fonts/Blix-Bold.otf") format("opentype");
  font-weight: 700;
  font-style: normal;
  font-display: swap;
}
/* ─── 5. Typography: Body ───────────────────────────────────────────────── */
p,
li,
span,
figcaption {
  font-family: "Inter", "Helvetica Neue", Helvetica, Arial, "Segoe UI", "Blix", "IBM Plex Sans TC", "PingFang TC", sans-serif;
  font-size: 1rem;
  line-height: 1.7;
  font-weight: 500;
}

p {
  margin-bottom: 1.4em;
}

blockquote {
  font-family: "Inter", "Helvetica Neue", Helvetica, Arial, sans-serif !important;
  font-size: 1rem !important;
  color: var(--black);
  background: none;
  border-left: none !important;
  padding: 0 0 0 2rem;
  margin: 2rem 0;
  letter-spacing: 0;
}

blockquote p,
blockquote li {
  font-family: "Inter", "Helvetica Neue", Helvetica, Arial, sans-serif !important;
  font-size: 1rem !important;
  color: var(--black) !important;
}

code,
pre {
  font-family: "JetBrains Mono", "Fira Mono", monospace !important;
  font-size: 0.8rem !important;
}

/* ─── 6. Typography: Headings ───────────────────────────────────────────── */
h1,
h2,
h3,
h4,
h5,
h6 {
  /* Inter for Latin; GenSekiGothicTW for CJK; Blix as CJK fallback */
  font-family: "Inter", "Helvetica Neue", Helvetica, Arial, "GenSekiGothicTW", "Blix", "PingFang TC", sans-serif !important;
  color: var(--black) !important;
  font-weight: 400;
  letter-spacing: -0.04em;
  line-height: 1.1;
}

h1 {
  font-size: 2.1rem;
}

h2 {
  font-size: 1.65rem;
}

h3 {
  font-size: 1.35rem;
}

h4 {
  font-size: 1.15rem;
}

h5 {
  font-size: 1rem;
}

h6 {
  font-size: 0.9rem;
}

/* Metadata labels: dates, categories, tags */
.post-meta,
time {
  font-size: 0.72rem;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  font-weight: 400;
}

/* ─── 7. Links ───────────────────────────────────────────────────────────── */
a {
  color: var(--black);
  text-decoration: none;
}

a:hover {
  color: var(--hover-text) !important;
  background-color: var(--hover-bg) !important;
  text-decoration: none !important;
}

/* Prevent inversion from bleeding into thumbnails */
a:hover img {
  background: transparent !important;
  filter: none;
}

/* ─── 8. Site header ────────────────────────────────────────────────────── */
html[data-header-transparent] header.site-header,
header.site-header {
  background: var(--white) !important;
  box-shadow: none !important;
  border-bottom: none !important;
}

html[data-header-transparent] header.site-header {
  position: sticky !important;
  top: 0;
  transition: top 0.3s ease;
  z-index: 1000;
}

html[data-scroll-status=down] header.site-header {
  top: -64px;
}

html[data-scroll-status=up],
html[data-scroll-status=top] header.site-header {
  top: 0;
}

html[data-header-transparent] header.site-header .site-brand-inner,
html[data-header-transparent] header.site-header .page-link {
  color: var(--black);
}

.site-header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  position: relative;
}

/* Hide the small favicon/logo in the navbar */
.site-favicon {
  display: none !important;
}

/* Brand / site title: regular weight, compact */
.site-brand .site-brand-inner {
  font-family: "Inter", "Helvetica Neue", Helvetica, Arial, "Blix", "PingFang TC", sans-serif;
  font-size: 1rem;
  font-weight: 400;
  letter-spacing: 0;
  color: var(--black);
}

.site-brand .site-brand-inner:hover,
.site-brand .site-brand-inner:visited:hover {
  color: var(--hover-text) !important;
  background-color: var(--hover-bg) !important;
}

/* Hide Jekyll's built-in checkbox nav — we use the hamburger */
.page-link,
label[for=nav-trigger],
.menu-icon {
  display: none !important;
}

.site-nav {
  font-size: 0.85rem;
  line-height: 63.84px;
  position: absolute;
  right: 0;
  top: 0;
}

/* ─── 9. Search toggle ───────────────────────────────────────────────────── */
.search-toggle {
  background: none;
  border: none;
  cursor: pointer;
  margin-right: 60px;
  display: flex;
  align-items: center;
  height: 40px;
  color: var(--black);
}

.search-toggle:hover {
  color: var(--hover-text) !important;
  background-color: var(--hover-bg) !important;
}

/* ─── 10. Hamburger menu ─────────────────────────────────────────────────── */
.menu-toggle {
  width: 30px;
  height: 22px;
  cursor: pointer;
  z-index: 1001;
  display: block;
  position: absolute;
  top: 18px;
  right: 20px;
}
.menu-toggle span {
  display: block;
  height: 2px;
  background: var(--black);
  margin: 6px 0;
}
.menu-toggle.open span:nth-child(1) {
  transform: rotate(45deg) translate(5px, 5px);
}
.menu-toggle.open span:nth-child(2) {
  opacity: 0;
}
.menu-toggle.open span:nth-child(3) {
  transform: rotate(-45deg) translate(6px, -6px);
}

.menu-wrapper {
  max-height: 0;
  opacity: 0;
  overflow: hidden;
  background: var(--white);
  border: 1px solid var(--black);
  position: absolute;
  top: 60px;
  right: 0;
  width: 160px;
  max-width: 90vw;
  z-index: 1000;
  display: flex;
  justify-content: flex-start;
}
.menu-wrapper ul {
  display: flex;
  flex-direction: column;
  list-style: none;
  padding: 0.5rem 0;
  margin: 0;
  width: 100%;
}
.menu-wrapper ul li {
  margin: 0;
}
.menu-wrapper ul li a {
  font-family: "Inter", "Helvetica Neue", Helvetica, Arial, sans-serif;
  font-size: 1rem;
  font-weight: 700;
  color: var(--black);
  text-decoration: none;
  padding: 0.5rem 1rem;
  display: block;
  text-align: left;
}
.menu-wrapper ul li a:hover {
  color: var(--hover-text) !important;
  background-color: var(--hover-bg) !important;
}
.menu-wrapper.open {
  max-height: 400px;
  opacity: 1;
}

/* ─── 11. Page layout & wrapper ─────────────────────────────────────────── */
.page-content {
  padding: 0 !important;
}

.wrapper {
  max-width: 1000px;
  margin: auto;
  padding-left: 2rem;
  padding-right: 2rem;
}

/* ─── 12. Post list (homepage / articles) ───────────────────────────────── */
.pagination .post-list {
  margin-left: 0;
  list-style: none;
  /* Remove the nth-child separator set in _layout.scss */
}
.pagination .post-list > li {
  background: transparent !important;
  padding: 4rem 0;
  margin-bottom: 0;
  border: none !important;
  border-bottom: none !important;
}
.pagination .post-list > li:hover {
  transform: none !important;
  border: none !important;
  background: transparent !important;
}
.pagination .post-list > li:not(:last-child) {
  border-bottom: none !important;
}
.pagination .post-title {
  margin-bottom: 0.4rem;
}
.pagination .post-title a {
  text-decoration: none;
}
.pagination .post-link {
  font-family: "Inter", "Helvetica Neue", Helvetica, Arial, sans-serif !important;
  font-size: 1.2rem !important;
  font-weight: 400 !important;
  letter-spacing: -0.03em;
  color: var(--black) !important;
}
.pagination .post-meta {
  font-size: 0.72rem !important;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--black) !important;
  opacity: 0.45;
  margin-bottom: 0.6rem;
}
.pagination .post-text {
  color: var(--black) !important;
  font-size: 0.85rem;
}
.pagination .post-tags .post-tag {
  border: none !important;
  font-size: 0.72rem !important;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--black) !important;
  padding: 0;
  margin-right: 0.75rem;
}
.pagination .post-tags .post-tag:hover {
  color: var(--hover-text) !important;
  background-color: var(--hover-bg) !important;
}
.pagination .paginator {
  padding: 2rem 0 4rem;
  text-align: left;
  /* Remove CSS-border chevrons — keep them but strip the visual border */
}
.pagination .paginator .previous,
.pagination .paginator .next {
  font-weight: 700;
  font-size: 0.85rem;
  color: var(--black);
}
.pagination .paginator .previous:hover,
.pagination .paginator .next:hover {
  color: var(--hover-text) !important;
  background-color: var(--hover-bg) !important;
}
.pagination .paginator .previous span,
.pagination .paginator .next span {
  color: rgba(17, 17, 17, 0.3);
}
.pagination .paginator > .previous:before, .pagination .paginator > .next:after {
  border-color: rgba(17, 17, 17, 0.4) !important;
}
.pagination .paginator .indicator {
  padding: 0 1rem;
  font-size: 0.8rem;
  opacity: 0.45;
}

/* ─── 13. Single post ───────────────────────────────────────────────────── */
.post .post-header {
  max-width: 760px;
  margin: 4rem auto 2rem;
  padding: 0 0 2rem;
  border: none !important;
}
.post .post-header .post-title {
  font-size: 2rem !important;
  letter-spacing: -0.04em;
  line-height: 1.1 !important;
  margin-bottom: 0.75rem;
  font-weight: 400;
}
.post .post-header .post-subtitle {
  font-size: 1rem !important;
  font-weight: 400;
  color: var(--black);
  opacity: 0.55;
  margin-bottom: 0.4rem;
}
.post .post-header .post-meta {
  font-size: 0.72rem !important;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--black) !important;
  opacity: 0.45;
  padding-bottom: 0;
}
.post .post-header .post-tags {
  padding-right: 0;
}
.post .post-header .post-tags .post-tag {
  border: none !important;
  font-size: 0.72rem !important;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--black);
  margin-right: 0.75rem;
}
.post .post-header .post-tags .post-tag:hover {
  color: var(--hover-text) !important;
  background-color: var(--hover-bg) !important;
}

/* Constrain article width */
.post-content,
.post-header {
  max-width: 760px;
  margin-left: auto;
  margin-right: auto;
}

.post-content {
  margin-bottom: 0;
  /* Horizontal rule: pure whitespace, no line */
}
.post-content h1 {
  font-size: 1.8rem !important;
  letter-spacing: -0.04em;
  line-height: 1.1 !important;
  margin: 3.5rem 0 1.25rem;
}
.post-content h2 {
  font-size: 1.5rem !important;
  letter-spacing: -0.04em;
  line-height: 1.1 !important;
  margin: 3rem 0 1rem;
}
.post-content h3 {
  font-size: 1.3rem !important;
  letter-spacing: -0.04em;
  line-height: 1.1 !important;
  margin: 2.5rem 0 0.75rem;
}
.post-content h4 {
  font-size: 1.1rem !important;
  letter-spacing: -0.03em;
  margin: 2rem 0 0.5rem;
}
.post-content h5,
.post-content h6 {
  font-size: 1rem !important;
  letter-spacing: -0.02em;
  margin: 1.5rem 0 0.5rem;
}
.post-content hr {
  height: 0;
  background: none;
  border: none;
  margin: 3rem 0;
}
.post-content img,
.post-content svg,
.post-content iframe {
  margin-left: auto;
  margin-right: auto;
  display: block;
  max-height: 70vh;
}

/* Related posts section */
.post-related {
  max-width: 760px;
  margin: 0 auto;
}
.post-related > *:first-child {
  font-size: 0.72rem !important;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  font-weight: 700;
  color: var(--black) !important;
  opacity: 0.45;
  margin-bottom: 0.75rem;
}
.post-related .post-link {
  font-size: 1rem !important;
  color: var(--black) !important;
}
.post-related .post-link:hover {
  color: var(--hover-text) !important;
  background-color: var(--hover-bg) !important;
}

/* ─── 14. Post navigation (prev / next) ─────────────────────────────────── */
/* Override both the theme's .post-nav AND the custom classes from old design */
.post-nav {
  display: flex;
  justify-content: space-between;
  max-width: 760px;
  margin: 4rem auto;
  padding-top: 0;
  border-top: none !important;
  gap: 2rem;
  /* Replace CSS-border arrows with text characters */
}
.post-nav a {
  font-family: "Inter", "Helvetica Neue", Helvetica, Arial, sans-serif;
  font-size: 0.85rem;
  color: var(--black) !important;
  font-weight: 400;
  max-width: 45%;
  display: flex;
  align-items: center;
}
.post-nav a:hover {
  color: var(--hover-text) !important;
  background-color: var(--hover-bg) !important;
}
.post-nav a * {
  overflow: hidden;
  text-wrap-mode: nowrap;
  text-overflow: ellipsis;
}
.post-nav .previous:before {
  content: "←";
  border: none !important;
  margin-right: 0.5rem;
  padding: 0;
}
.post-nav .next:after {
  content: "→";
  border: none !important;
  margin-left: 0.5rem;
  padding: 0;
}

/* Old custom post-nav class variants */
.post-nav-item {
  width: 48%;
}

.post-nav-next {
  text-align: right;
}

.post-nav-link {
  display: block;
  padding: 0;
  border: none !important;
  background: transparent !important;
  color: var(--black);
}
.post-nav-link:hover {
  background-color: transparent !important;
}

.post-nav-title {
  font-size: 0.85rem;
  font-weight: 700;
  margin-top: 0.25rem;
}

/* ─── 15. Page banner ───────────────────────────────────────────────────── */
.page-banner {
  background-image: none !important;
  background-color: var(--white) !important;
}

.page-banner-inner {
  text-shadow: none !important;
}
.page-banner-inner .left-vsplit:before {
  background: transparent;
}
.page-banner-inner .post-subtitle,
.page-banner-inner .post-meta {
  color: rgba(17, 17, 17, 0.55) !important;
}
.page-banner-inner .post-tags .post-tag {
  color: var(--black) !important;
  border: none !important;
}

h1.page-banner-heading,
h2.page-banner-heading,
h3.page-banner-heading,
h4.page-banner-heading,
h5.page-banner-heading,
h6.page-banner-heading,
h1.page-banner-subheading,
h2.page-banner-subheading,
h3.page-banner-subheading,
h4.page-banner-subheading,
h5.page-banner-subheading,
h6.page-banner-subheading {
  font-family: "Satoshi", "Helvetica Neue", "GenSekiGothicTW", "Blix", sans-serif !important;
  font-size: 2.2rem !important;
  color: var(--black) !important;
  font-weight: 500 !important;
  letter-spacing: -0.04em !important;
  line-height: 1.1 !important;
  border: none !important;
  background: none !important;
  padding: 0 !important;
  margin: 0 !important;
  text-align: left;
  text-shadow: none !important;
}

.page-banner-heading::before,
.page-banner-heading::after,
.page-banner-subheading::before,
.page-banner-subheading::after {
  content: none !important;
  border: none !important;
}

/* ─── 16. Site footer ───────────────────────────────────────────────────── */
.site-footer {
  background-color: var(--white) !important;
  color: var(--black) !important;
  border: none !important;
  font-size: 0.75rem;
}
.site-footer .site-footer-inner {
  border-top: none !important;
  padding: 4rem 0 2rem;
}
.site-footer a {
  color: var(--black);
}
.site-footer a:hover {
  color: var(--hover-text) !important;
  background-color: var(--hover-bg) !important;
}

/* ─── 17. Tables ────────────────────────────────────────────────────────── */
table {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.8rem;
  margin-bottom: 2rem;
  color: var(--black) !important;
}
table tr:nth-child(even) {
  background-color: transparent !important;
}
table th,
table td {
  border: 1px solid rgba(17, 17, 17, 0.15) !important;
  padding: 0.5rem 0.75rem;
  background: transparent !important;
  text-align: left;
  font-size: 0.8rem;
  color: var(--black);
}
table th {
  font-weight: 700;
  border-color: rgba(17, 17, 17, 0.35) !important;
  background: transparent !important;
}

/* Explicit simple-table class (used in posts) */
table.simple-table th,
table.simple-table td {
  border: 1px solid rgba(17, 17, 17, 0.15);
  padding: 0.5rem 0.75rem;
  background: transparent;
}
table.simple-table th {
  font-weight: 700;
  border-color: rgba(17, 17, 17, 0.35);
  background: transparent !important;
}
table.simple-table tbody tr:hover > td,
table.simple-table tbody tr:hover > th {
  background: rgba(17, 17, 17, 0.03) !important;
}

/* ─── 18. Search overlay ────────────────────────────────────────────────── */
.search-overlay {
  position: fixed;
  inset: 0;
  z-index: 9999;
  display: flex;
  justify-content: center;
  align-items: flex-start;
  padding: 10vh 2rem;
  background: rgba(255, 255, 255, 0.95);
  backdrop-filter: none;
  -webkit-backdrop-filter: none;
}

.search-overlay.hidden {
  display: none;
}

.search-panel {
  position: relative;
  width: var(--search-width);
  padding: 1.25rem 1.25rem 0;
  background: var(--white);
  border: 1px solid var(--black);
}

.search-header {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  padding-right: 0;
}

.search-header #search-input {
  flex: 1;
  font-size: var(--search-input-font);
  padding: 1rem 1.25rem;
  min-height: 52px;
  line-height: 1.35;
}

#search-input[type=search]::-webkit-search-cancel-button,
#search-input[type=search]::-webkit-search-decoration {
  -webkit-appearance: none;
  appearance: none;
  display: none;
}

#search-input[type=search]::-ms-clear {
  display: none;
  width: 0;
  height: 0;
}

#search-input {
  background: transparent;
  border: none;
  outline: none;
  padding: 0.9rem 1.1rem;
  color: var(--black);
  font-family: "Inter", "Helvetica Neue", Helvetica, Arial, sans-serif;
}

#search-results {
  max-height: 70vh;
  overflow: auto;
  margin-top: 0.75rem;
}

.search-item {
  border-top: none !important;
  padding: 1rem 1.25rem;
}
.search-item:hover {
  background: var(--hover-bg) !important;
}
.search-item:hover * {
  color: var(--hover-text) !important;
}

#search-close {
  position: static !important;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 42px;
  min-height: 42px;
  padding: 0.4rem 0.65rem;
  font-size: 20px;
  background: transparent;
  border: none;
  cursor: pointer;
  opacity: 0.7;
  color: var(--black);
}
#search-close:hover {
  opacity: 1;
  background: var(--hover-bg) !important;
  color: var(--hover-text) !important;
}

.search-title {
  font-weight: 700;
  font-size: var(--search-title-font);
  color: var(--black);
}

.search-snippet {
  margin-top: 0.35rem;
  font-size: var(--search-snippet-font);
  opacity: 0.8;
  color: var(--black);
}

mark {
  background: rgba(0, 0, 255, 0.12);
  padding: 0 0.1em;
}

/* ─── 19. Header inline search form ─────────────────────────────────────── */
.header-search-form {
  opacity: 0;
  pointer-events: none;
  transform: translateY(-10px);
  transition: opacity 0.2s, transform 0.2s;
  position: absolute;
  top: 60px;
  right: 24px;
  z-index: 1000;
  background: var(--white);
  border: 1px solid var(--black);
  padding: 0.5rem 1rem;
}
.header-search-form.show {
  opacity: 1;
  pointer-events: auto;
  transform: translateY(0);
}
.header-search-form input {
  font-family: "Inter", "Helvetica Neue", Helvetica, Arial, sans-serif;
  font-size: 0.85rem;
  padding: 0.25rem 0.5rem;
  border: none;
  background: transparent;
  color: var(--black);
  outline: none;
  width: 160px;
}

/* ─── 20. Archives ──────────────────────────────────────────────────────── */
.page-archives .page-archives-list {
  margin-left: 0;
  list-style: none;
}
.page-archives .archives-time {
  font-size: 0.72rem !important;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  font-weight: 700;
  margin-top: 3rem;
  margin-bottom: 0.75rem;
}
.page-archives .post-meta {
  font-size: 0.72rem;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  opacity: 0.45;
}

/* ─── 21. Segments (categories / tags pages) ─────────────────────────────── */
.page-segments .page-segments-list {
  margin-left: 0;
  list-style: none;
}
.page-segments .segment-name {
  font-size: 0.72rem !important;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  font-weight: 700;
  margin-top: 3rem;
  margin-bottom: 0.75rem;
  /* Remove '#' hover pseudo-element */
}
.page-segments .segment-name:hover:before {
  content: none;
}
.page-segments .post-meta {
  font-size: 0.72rem;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  opacity: 0.45;
}
.page-segments li a {
  color: var(--black);
  font-size: 0.85rem;
}
.page-segments li a:hover {
  color: var(--hover-text) !important;
  background-color: var(--hover-bg) !important;
}
.page-segments li a.post-link {
  margin-left: 0.5rem;
}

/* ─── 22. Vertical split separator — remove ─────────────────────────────── */
.left-vsplit:before {
  display: none;
}

/* ─── 23. Post badges ───────────────────────────────────────────────────── */
.post-badge {
  background-color: var(--black) !important;
  color: var(--white) !important;
  font-size: 0.55rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  padding: 0 3px;
}

/* ─── 24. Dark mode — keep pure white regardless of OS preference ────────── */
@media (prefers-color-scheme: dark) {
  :root {
    --white: #FFFFFF;
    --black: #111111;
  }
  html,
  body,
  .page-content,
  .site-header,
  .site-footer {
    background-color: #FFFFFF !important;
    color: #111111 !important;
  }
}
html[data-theme=dark] {
  --white: #FFFFFF;
  --black: #111111;
}

html[data-theme=dark],
html[data-theme=dark] body,
html[data-theme=dark] .page-content,
html[data-theme=dark] .site-header,
html[data-theme=dark] .site-footer {
  background-color: #FFFFFF !important;
  color: #111111 !important;
}

/* ─── 25. Responsive: tablet (≤ 800px) ──────────────────────────────────── */
@media screen and (max-width: 800px) {
  .wrapper {
    padding-left: 1.5rem;
    padding-right: 1.5rem;
  }
  .pagination .post-list > li {
    padding: 2.5rem 0;
  }
  .post .post-header {
    margin: 2.5rem auto 1.5rem;
  }
  .post-nav {
    flex-direction: column;
    gap: 1.5rem;
    margin: 3rem auto;
  }
  .post-nav-item,
  .post-nav a {
    width: 100% !important;
    max-width: 100% !important;
  }
  .post-nav-next {
    text-align: left;
  }
}
/* ─── 26. Responsive: mobile (≤ 480px) ──────────────────────────────────── */
@media screen and (max-width: 480px) {
  .wrapper {
    padding-left: 1rem;
    padding-right: 1rem;
  }
  .pagination .post-list > li {
    padding: 2rem 0;
  }
  .search-panel {
    width: min(94vw, 720px);
  }
  .search-header #search-input {
    min-height: 48px;
  }
  h1.page-banner-heading,
  h2.page-banner-heading,
  h3.page-banner-heading,
  h4.page-banner-heading,
  h5.page-banner-heading,
  h6.page-banner-heading,
  h1.page-banner-subheading,
  h2.page-banner-subheading,
  h3.page-banner-subheading,
  h4.page-banner-subheading,
  h5.page-banner-subheading,
  h6.page-banner-subheading {
    font-size: 1.5rem !important;
  }
}
/* ─── 27. Responsive: banner headings (≤ 768px) ─────────────────────────── */
@media screen and (max-width: 768px) {
  h1.page-banner-heading,
  h2.page-banner-heading,
  h3.page-banner-heading,
  h4.page-banner-heading,
  h5.page-banner-heading,
  h6.page-banner-heading,
  h1.page-banner-subheading,
  h2.page-banner-subheading,
  h3.page-banner-subheading,
  h4.page-banner-subheading,
  h5.page-banner-subheading,
  h6.page-banner-subheading {
    font-size: 1.75rem !important;
  }
}
/* ═══════════════════════════════════════════════════════════════════════════
   28. MAGAZINE LAYOUT — Swiss/Brutalist editorial grid
   ═══════════════════════════════════════════════════════════════════════════ */
/* — Narrow wrapper: tight left/right margins, full-bleed feel — */
.wrapper {
  max-width: 1400px;
  padding-left: 2rem;
  padding-right: 2rem;
}

/* — Header: thin bottom rule, no bg, no shadow — */
.site-header {
  border-bottom: 1.5px solid var(--black) !important;
  padding-top: 0.6rem;
  padding-bottom: 0.6rem;
}

/* — Brand: uppercase mono-style label — */
.site-brand .site-brand-inner {
  font-size: 1rem !important;
  font-weight: 700 !important;
  text-transform: uppercase !important;
  letter-spacing: 0.12em !important;
}

/* — Desktop nav: inline layout — */
@media screen and (min-width: 801px) {
  /* Hamburger: hide */
  .menu-toggle {
    display: none !important;
  }
  /* Pull old .site-nav out of absolute positioning into flex flow */
  .site-nav {
    position: static !important;
    line-height: 1 !important;
    display: flex !important;
    align-items: center !important;
    margin-left: auto; /* push nav + search to the right */
    font-size: 0 !important; /* collapse the checkbox whitespace */
  }
  /* Show trigger items inline */
  .site-nav .trigger {
    display: flex !important;
    align-items: center !important;
  }
  label[for=nav-trigger],
  .menu-icon {
    display: none !important;
  }
  .site-nav .trigger .page-link {
    display: inline-flex !important;
    align-items: center !important;
    font-size: 1rem !important;
    font-weight: 700 !important;
    text-transform: uppercase !important;
    letter-spacing: 0.1em !important;
    padding: 0.3rem 0.75rem !important;
    color: var(--black) !important;
    text-decoration: none !important;
    white-space: nowrap !important;
  }
  .site-nav .trigger .page-link:hover {
    color: var(--hover-text) !important;
    background-color: var(--hover-bg) !important;
  }
  /* Search toggle: no right-margin gap for hamburger */
  .search-toggle {
    margin-right: 0 !important;
  }
}
/* — Hide banner entirely on homepage (no heading set) — */
.page-banner:not(:has(h1, h2, h3, h4, h5, h6)) {
  display: none !important;
}

/* — Hide sidebar on list/pagination pages — */
.framework:has(.pagination) .sidebar {
  display: none !important;
}

/* — Post list header row — */
.post-list-header {
  display: grid;
  grid-template-columns: 2.5rem 6rem 1fr auto;
  grid-template-areas: "num date title tags";
  align-items: baseline;
  padding: 0.4rem 0;
  border-top: 1.5px solid var(--black);
  border-bottom: 1px solid var(--black);
  margin-bottom: 0;
  font-size: 0.62rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--black);
  opacity: 0.5;
}
.post-list-header .col-num {
  grid-area: num;
}
.post-list-header .col-date {
  grid-area: date;
}
.post-list-header .col-title {
  grid-area: title;
}
.post-list-header .col-tags {
  grid-area: tags;
  text-align: right;
  padding-right: 0.5rem;
}

/* — Post list: reset default card style — */
.pagination .post-list {
  list-style: none;
  margin: 0;
  padding: 0;
  counter-reset: post-counter;
  /* Pin badge on top post */
}
.pagination .post-list > li.post-item,
.pagination .post-list > li.top-post {
  counter-increment: post-counter;
  display: grid;
  grid-template-columns: 2.5rem 6rem 1fr auto;
  grid-template-areas: "num date title tags";
  align-items: baseline;
  padding: 0.75rem 0;
  border-bottom: 1px solid rgba(17, 17, 17, 0.12);
  gap: 0;
  margin: 0;
  /* Remove old card padding/background */
  background: transparent !important;
  box-shadow: none !important;
  /* Counter number */
  /* Hide everything we don't want */
