  /* Post meta wrapper — flatten */
}
.pagination .post-list > li.post-item::before,
.pagination .post-list > li.top-post::before {
  content: counter(post-counter, decimal-leading-zero);
  grid-area: num;
  font-size: 0.65rem;
  font-weight: 700;
  color: var(--black);
  opacity: 0.35;
  align-self: center;
}
.pagination .post-list > li.post-item .post-excerpt,
.pagination .post-list > li.post-item .post-author,
.pagination .post-list > li.post-item .post-reading-time,
.pagination .post-list > li.post-item .post-image,
.pagination .post-list > li.post-item .post-text,
.pagination .post-list > li.post-item .left-vsplit,
.pagination .post-list > li.post-item .fa,
.pagination .post-list > li.post-item .fa-solid,
.pagination .post-list > li.post-item .fa-regular,
.pagination .post-list > li.top-post .post-excerpt,
.pagination .post-list > li.top-post .post-author,
.pagination .post-list > li.top-post .post-reading-time,
.pagination .post-list > li.top-post .post-image,
.pagination .post-list > li.top-post .post-text,
.pagination .post-list > li.top-post .left-vsplit,
.pagination .post-list > li.top-post .fa,
.pagination .post-list > li.top-post .fa-solid,
.pagination .post-list > li.top-post .fa-regular {
  display: none !important;
}
.pagination .post-list > li.post-item .post-date,
.pagination .post-list > li.top-post .post-date {
  grid-area: date;
  font-size: 0.7rem;
  font-weight: 400;
  color: var(--black);
  opacity: 0.5;
  letter-spacing: 0;
  align-self: center;
}
.pagination .post-list > li.post-item .post-title,
.pagination .post-list > li.top-post .post-title {
  grid-area: title;
  margin: 0;
  padding: 0;
  align-self: center;
}
.pagination .post-list > li.post-item .post-title .post-link,
.pagination .post-list > li.top-post .post-title .post-link {
  font-size: 0.95rem;
  font-weight: 500;
  color: var(--black);
  text-decoration: none;
  letter-spacing: -0.01em;
  line-height: 1.3;
  display: block;
  padding: 0.1rem 0.5rem;
}
.pagination .post-list > li.post-item .post-title .post-link:hover,
.pagination .post-list > li.top-post .post-title .post-link:hover {
  color: var(--hover-text) !important;
  background-color: var(--hover-bg) !important;
}
.pagination .post-list > li.post-item .post-tags,
.pagination .post-list > li.top-post .post-tags {
  grid-area: tags;
  display: flex;
  gap: 0.35rem;
  align-items: center;
  justify-content: flex-end;
  padding-right: 0.25rem;
}
.pagination .post-list > li.post-item .post-tags .post-tag,
.pagination .post-list > li.top-post .post-tags .post-tag {
  font-size: 0.58rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.07em;
  padding: 0.1rem 0.4rem;
  color: var(--black);
  background: transparent;
  border: 1px solid var(--black);
  text-decoration: none;
}
.pagination .post-list > li.post-item .post-tags .post-tag:hover,
.pagination .post-list > li.top-post .post-tags .post-tag:hover {
  color: var(--hover-text) !important;
  background-color: var(--hover-bg) !important;
  border-color: var(--hover-text) !important;
}
.pagination .post-list > li.post-item .post-meta,
.pagination .post-list > li.top-post .post-meta {
  display: contents;
}
.pagination .post-list > li.top-post .post-badge {
  display: inline-block !important;
}

/* — Paginator links — */
.paginator {
  margin-top: 2rem;
  font-size: 0.7rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
}
.paginator a {
  color: var(--black);
  padding: 0.2rem 0.5rem;
  text-decoration: none;
}
.paginator a:hover {
  color: var(--hover-text) !important;
  background-color: var(--hover-bg) !important;
}

/* — Mobile (≤ 640px): collapse to 2-column — */
@media screen and (max-width: 640px) {
  .wrapper {
    padding-left: 1rem;
    padding-right: 1rem;
  }
  .post-list-header {
    grid-template-columns: 2.5rem 1fr;
    grid-template-areas: "num title";
  }
  .post-list-header .col-date,
  .post-list-header .col-tags {
    display: none;
  }
  .pagination .post-list > li.post-item,
  .pagination .post-list > li.top-post {
    grid-template-columns: 2.5rem 1fr;
    grid-template-areas: "num title" ".   tags";
  }
  .pagination .post-list > li.post-item .post-date,
  .pagination .post-list > li.top-post .post-date {
    display: none;
  }
  .pagination .post-list > li.post-item .post-tags,
  .pagination .post-list > li.top-post .post-tags {
    justify-content: flex-start;
    padding-left: 0;
  }
}
/* ─── 29. Google Translate widget — brutalist reset ─────────────────────── */
/* Trigger button */
.ct-language {
  background-color: transparent !important;
  border-radius: 0 !important;
  padding: 0.3rem 0.75rem !important;
}
.ct-language:before {
  font-size: 0.68rem;
  font-family: "Inter", "Helvetica Neue", Helvetica, Arial, sans-serif;
  content: "TR ▾" !important; /* plain text label + small arrow */
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--black);
  font-family: inherit !important;
}
.ct-language:hover {
  background-color: var(--hover-bg) !important;
}
.ct-language:hover:before {
  color: var(--hover-text);
}

/* Dropdown panel */
.ct-language-dropdown {
  border-radius: 0 !important;
  transition: none !important;
  -webkit-transition: none !important;
  box-shadow: none !important;
  -webkit-box-shadow: none !important;
  background-color: var(--white) !important;
  border: 1px solid var(--black) !important;
  width: 110px !important;
  right: 0 !important;
  top: 100% !important;
}
.ct-language-dropdown li {
  padding: 0 !important;
  border-bottom: none !important;
}
.ct-language-dropdown li:first-child {
  padding-top: 0 !important;
}
.ct-language-dropdown li:last-child {
  padding-bottom: 0 !important;
}
.ct-language-dropdown li a {
  display: flex !important;
  align-items: center !important;
  gap: 0.4rem !important;
  padding: 0.35rem 0.6rem !important;
  font-size: 0.68rem !important;
  font-weight: 700 !important;
  text-transform: uppercase !important;
  letter-spacing: 0.08em !important;
  color: var(--black) !important;
  text-decoration: none !important;
}
.ct-language-dropdown li a img {
  width: 16px !important;
  height: auto !important;
  flex-shrink: 0 !important;
}
.ct-language-dropdown li a:hover {
  background-color: var(--hover-bg) !important;
  color: var(--hover-text) !important;
}

/* Show on hover (instant) */
.ct-language:hover .ct-language-dropdown {
  max-height: 10000px !important;
  visibility: visible !important;
  margin-top: 0 !important;
}

.ct-language-selected, .ct-language-dropdown li:hover {
  background-color: transparent !important;
}

