AAGF;EACA;IACE;IACA;;EAGF;AAAA;IAEE;;EAGF;IACE;IACA;IACA;IACA;IACA;IACA;IACA;IACA;IACA;IACA;;EAEA;IACE;IACA;;AAIJ;EACA;IACE;;;AAIJ;AACA;EACE;;;AAGF;AACA;EACE;;;AAGF;AACA;EACE;EACA;EACA;EACA;EACA;EACA;EACA;EACA;EACA;EACA;EACA;EACA;EACA;EACA;;AAEA;EAAa;;AACb;EAAa;;AACb;EAAa;;AACb;EAAa;EAAiB;EAAmB;;;AAGnD;AACA;EACE;EACA;EACA;EACA;AA+GA;;AA7GA;AAAA;EAEE;EACA;EACA;EACA;EACA;EACA;EACA;EACA;EACA;AAEA;EACA;EACA;AAEA;AAWA;AAaA;AAWA;AAwBA;AA4BA;;AAtFA;AAAA;EACE;EACA;EACA;EACA;EACA;EACA;EACA;;AAIF;AAAA;AAAA;AAAA;AAAA;AAAA;AAAA;AAAA;AAAA;AAAA;AAAA;AAAA;AAAA;AAAA;AAAA;AAAA;AAAA;AAAA;EASE;;AAIF;AAAA;EACE;EACA;EACA;EACA;EACA;EACA;EACA;;AAIF;AAAA;EACE;EACA;EACA;EACA;;AAEA;AAAA;EACE;EACA;EACA;EACA;EACA;EACA;EACA;EACA;;AAEA;AAAA;EACE;EACA;;AAMN;AAAA;EACE;EACA;EACA;EACA;EACA;EACA;;AAEA;AAAA;EACE;EACA;EACA;EACA;EACA;EACA;EACA;EACA;EACA;;AAEA;AAAA;EACE;EACA;EACA;;AAMN;AAAA;EACE;;AAKJ;EACE;;;AAIJ;AACA;EACE;EACA;EACA;EACA;EACA;;AAEA;EACE;EACA;EACA;;AAEA;EACE;EACA;;;AAKN;AACA;EACE;IACE;IACA;;EAGF;IACE;IACA;;EAEA;AAAA;IAEE;;EAIJ;AAAA;IAEE;IACA,qBACE;;EAGF;AAAA;IACE;;EAGF;AAAA;IACE;IACA;;;AAKN;AAEA;AACA;EACE;EACA;EACA;;AAEA;EACE;EACA;EACA;EACA;EACA;EACA;EACA;EACA;;AAGF;EACE;;AAEA;EACE;;;AAKN;AACA;EACE;EACA;EACA;EACA;EACA;EACA;EACA;EACA;EACA;EACA;;AAEA;EACE;EACA;;AAEA;EAAgB;;AAChB;EAAgB;;AAEhB;EACE;EACA;EACA;EACA;EACA;EACA;EACA;EACA;EACA;EACA;;AAEA;EACE;EACA;EACA;;AAGF;EACE;EACA;;;AAMR;AACA;EACE;EACA;EACA;;;AAGF;EACE","sourcesContent":["/* Variable overrides — pure white base for Swiss/Brutalist aesthetic */
$background-color: #ffffff !default;
$header-bg       : #ffffff !default;
$theme-color     : #ffffff !default;
$brand-color     : #0000FF;          // Pure blue accent
$card-background-color: #ffffff;

/* Banner height — compact title block (was 640px) */
$banner-height: 260px;
","@charset "utf-8";

/**
 * Reset some basic elements
 */
body, h1, h2, h3, h4, h5, h6,
p, blockquote, pre, hr,
dl, dd, ol, ul, figure {
  margin: 0;
  padding: 0;
}



/**
 * Basic styling
 */
body {
  font-family: $base-font-family;
  font-weight: $base-font-weight;
  font-size: #{$base-font-size};
  font-display: swap;
  line-height: #{$base-line-height};
  color: $text-color;
  background-color: $background-color;
  -webkit-text-size-adjust: 100%;
  -webkit-font-feature-settings: "kern" 1;
     -moz-font-feature-settings: "kern" 1;
       -o-font-feature-settings: "kern" 1;
          font-feature-settings: "kern" 1;
  font-kerning: normal;
  display: flex;
  min-height: 100vh;
  flex-direction: column;
  transition-duration: $base-transition-duration;
}

html[lang="ja"] body {
  font-family: 'Zen Maru Gothic Medium', sans-serif !important;
}



/**
 * Set `margin-bottom` to maintain vertical rhythm
 */
h1, h2, h3, h4, h5, h6,
p, blockquote, pre,
ul, ol, dl, figure,
%vertical-rhythm {
  margin-bottom: divide($spacing-unit, 2);
}



/**
 * `main` element
 */
main {
  display: block; /* Default value of `display` of `main` element is 'inline' in IE 11. */
}



/**
 * Images
 */
img {
  max-width: 100%;
  vertical-align: middle;
}



/**
 * Figures
 */
figure > img {
  display: block;
}

figcaption {
  font-size: $small-font-size;
}



/**
 * Lists
 */
ul, ol {
  margin-left: $spacing-unit;
}

li {
  > ul,
  > ol {
    margin-bottom: 0;
  }
}



/**
 * Headings
 */
h1, h2, h3, h4, h5, h6 {
  font-weight: $base-font-weight;
}
/**
 * Links
 */
a {
  color: $brand-color;
  text-decoration: none;

  &:hover {
    text-decoration: underline;
  }

  .social-media-list &:hover {
    text-decoration: none;

    .username {
      text-decoration: underline;
    }
  }
}

/**
 * Blockquotes
 */
blockquote {
  color: #3E3F40;
  border-left: 4px solid $grey-color-light;
  padding-left: divide($spacing-unit, 2);
  @include relative-font-size(1.125);
  letter-spacing: -1px;
  // font-style: italic;

  > :last-child {
    margin-bottom: 0;
  }
}



/**
 * Code formatting
 */
pre,
code {
  @include relative-font-size(0.9375);
  color: $text-color;
}

*:not(pre) > code {
  padding: 3px 6px;
  border-radius: 3px;
  background-color: #000000;
  margin: 0 5px;
}

pre {
  overflow-x: auto;
  position: relative;
  background-color: #f0f0f0;

  > code {
    display: inline-block;
    padding: 20px!important;
    background-color: transparent;
    border: 0;
  }

  table, pre {
    margin-bottom: 0;

    .gutter, .code {
      padding: 6px;
      border: none;
    }
  }
}



/**
 * Wrapper
 */
.wrapper {
  max-width: $content-width;
  margin: auto;
  padding-right: $spacing-unit;
  padding-left: $spacing-unit;
  @extend %clearfix;
}



/**
 * Clearfix
 */
%clearfix:after {
  content: "";
  display: table;
  clear: both;
}


/**
 * Tables
 */
table {
  display: block;
  margin-bottom: $spacing-unit;
  width: 100%;
  text-align: $table-text-align;
  color: lighten($text-color, 5%);
  border-collapse: collapse;
  overflow: auto;

  tr {
    &:nth-child(even) {
      background-color: lighten($grey-color-light, 6%);
    }
  }

  th, td {
    padding: divide($spacing-unit, 3) divide($spacing-unit, 2);
  }

  th {
    background-color: lighten($grey-color-light, 3%);
    border: 1px solid darken($grey-color-light, 4%);
    border-bottom-color: darken($grey-color-light, 12%);
  }

  td {
    border: 1px solid $grey-color-light;
  }
}

/**
 * Flex layout
 */
%flex {
  display: flex;
}

%flex-1 {
  flex: 1;
  min-width: 0; /*  svg {
              fill: $white-color;
            }
          }
        }
      }
    }

    footer.site-footer {
      color: unset;
      background-color: transparent;

      .site-footer-inner {
        border-top: solid 1px #eee;
      }
    }
  }

  &[data-scroll-status='down'] {
    header.site-header {
      top: -$header-height;
    }

    .framework .sidebar {
      top: 20px;
    }
  }
}

/**
 * Site header
 */
.site-header {
  background-color: $header-background-color;
  height: $header-height;
  width: 100%;
  transition: height 0.2s, text-shadow 0.2s, top 0.2s;
  box-shadow: 0 1px 0 0 rgba(0, 0, 0, .06);

  // Positioning context for the mobile navigation icon
  @include flex-sticky(0);
  z-index: 1000;

  & > .wrapper {
    margin: 0 60px;
    padding: 0;
    max-width: 100%;
    transition: 0.2s margin;

    @include media-query(1024px) {
      margin: 0 20px;
      max-width: unset;
    }
  }

  a {
    text-decoration: none;
  }

  .site-header-inner {
    position: relative;
  }
}

.site-brand {
  line-height: $header-height;
  margin-right: 50px;

  .site-brand-inner {
    @include relative-font-size(1.125);
    font-weight: $base-font-weight;
    letter-spacing: -1px;
    transition: 0.1s filter color;
    font-family: "jfhuninn", sans-serif;

    &, &:visited {
      color: $header-text-color;
    }

    .site-favicon {
      display: inline-block;
      height: divide($header-height, 1.5);
      margin-right: 5px;
    }
  }
}

.site-nav {
  @include relative-font-size(1.25);
  line-height: $header-height;
  position: absolute;
  right: 0;
  top: 0;

  .nav-trigger {
    display: none;
  }

  .menu-icon {
    display: none;
  }

  .page-link {
    line-height: $base-line-height;
    color: $header-text-color;
    transition: 0.1s ease-in-out;
    font-family: "jfhuninn", sans-serif;
    font-weight: 400;

    // Gaps between nav items, but not on the last one
    &:not(:last-child) {
      margin-right: 24px;
      &:hover {
        text-decoration: underline;
      }
    }
  }

  @include media-query($on-laptop) {
    position: absolute;
    top: 0;
    text-align: left;

    label[for="nav-trigger"] {
      display: block;
      z-index: 2;
      cursor: pointer;
    }

    .menu-icon {
      display: block;
      float: right;
      text-align: center;

      > svg {
        fill: rgba($header-text-color, 80%);
        transition: 0.1s fill;
      }
    }

    input ~ .trigger {
      clear: both;
      display: none;
      border-radius: 3px;
      box-shadow: 1px 1px 1px 1px rgba(0, 0, 0, .06);
    }

    input:checked ~ .trigger {
      display: block;
      background: $header-background-color;
    }

    .page-link {
      display: block;
      padding: 5px 10px;
      color: rgba($header-text-color, 80%);
      margin: 0 25px;
    }
  }
}

/**
 * Site footer
 */
.site-footer {
  @include relative-font-size(1.0);
  color: $footer-text-color;
  background-color: $footer-background-color;
  text-align: left;
  transition: background-color 0.2s;

  .site-footer-inner {
    transition: border-top 0.2s;
    padding: $spacing-unit * 1.8 0;
  }

  a {
    $a-color: $brand-color;
    color: $a-color;

    &:hover {
      color: lighten($a-color, 10%);
    }
  }
}

.copyleft {
  display: inline-block;
  transform: rotate(180deg);
}

/**
 * Post header
 */
%post-header {
  .post-header {
    margin-bottom: $spacing-unit;
  }

  .post-title {
    @include relative-font-size(3.0);
    letter-spacing: -1px;
    line-height: 1;

    @include media-query($on-laptop) {
      @include relative-font-size(2.5);
    }
  }

  .post-tags {
    padding-right: 150px;

    .post-tag {
      display: inline-block;
      margin: 0 12px 0 0;
    }
  }
}

/**
 * Page content
 */
.page-content {
  @extend %flex-1; /*  li {
      margin-bottom: $spacing-unit * 1.5;
      padding-bottom: 30px;

      &:not(:last-child) {
        border-bottom: 1px solid #e3e3e3;
      }
    }
  }

  .post-title {
    margin-bottom: $spacing-unit * 0.2;
    transition: 0.2s all;

    a {
      text-decoration: none;
    }
  }

  .post-link {
    @include relative-font-size(1.65);
    font-weight: $base-font-weight;
    color: #333;
  }

  .post-meta {
    color: #3E3F40;
    font-size: $base-font-size;
    margin-bottom: $spacing-unit * 0.5;
  }

  .post-excerpt {
    display: flex;
    position: relative;
    gap: 15px;
    margin-bottom: 15px;

    .post-image > *:first-child {
      flex: 0 1 38.2%;
      width: 100%;
      height: 100%;
      background-size: cover;
      background-position: center center;
      overflow: hidden;
      transition: 0.2s all ease-in-out;
    }
  }

  .post-list {
    &.none-image-style .post-item .post-excerpt .post-image {
      display: none;
    }

    &.left-image-style .post-item .post-excerpt {
      flex-direction: row;
    }

    &.right-image-style .post-item .post-excerpt {
      flex-direction: row-reverse;
    }

    &.post-list.top-image-style .post-item .post-excerpt {
      flex-direction: column;
    }

    &.z-image-style .post-item:nth-child(even) .post-excerpt {
      flex-direction: row-reverse;
    }

    &.z-reverse-image-style .post-item:nth-child(odd) .post-excerpt {
      flex-direction: row-reverse;
    }

    .post-item .post-excerpt {
      @include media-query($on-laptop) {
        flex-direction: column !important;
      }
    }
  }

  .post-text {
    color: #3E3F40;
    word-break: break-word;
    overflow-wrap: break-word;
    flex: 1;
  }

  .post-tags .post-tag {
    display: inline-block;
    text-decoration: none;
    border: 1px solid;
    padding: 2px 4px;
    border-radius: 2px;
    transition: color 0.2s;
    margin-bottom: 8px;

    &:not(:last-child) {
      margin-right: 8px;
    }

    &:hover {
      color: #787878;
    }
  }

  .paginator {
    text-align: center;

    & > .previous:before {
      content: ' ';
      border: solid #787878;
      border-width: 0 2px 2px 0;
      display: inline-block;
      padding: 4px;
      margin-right: 8px;
      transform: rotate(135deg);
      -webkit-transform: rotate(135deg);
    }

    & > .next:after {
      content: ' ';
      border: solid #787878;
      border-width: 0 2px 2px 0;
      display: inline-block;
      padding: 4px;
      margin-left: 8px;
      transform: rotate(-45deg);
      -webkit-transform: rotate(-45deg);
    }

    .previous span, .next span {
      color: #b3b3b3;
    }

    .indicator {
      padding: 0 15px;
    }
  }
}


/**
 * Posts
 */
.post {
  @extend %post-header;

  .post-header {
    margin: 50px auto 60px;
    padding: 0 0 20px;

    .post-title {
      margin-bottom: 6px;
    }

    .post-subtitle {
      font-weight: 400;
      font-size: 21px;
    }

    .post-meta {
      color: #3E3F40;
      padding-bottom: 15px;
    }
  }

.post-content {
  margin-bottom: $spacing-unit;
  overflow-wrap: normal;
  word-wrap: normal;
  word-break: normal;

  /* ---------- Headings ---------- */
  h1 {
    /* 約 36 px；在小螢幕縮到 28 px 左右 */
    @include relative-font-size(2.25);
    line-height: 1.25;
    margin: 72px 0 24px;

    @include media-query($on-laptop) {
      @include relative-font-size(1.75);
    }
  }

  h2 {
    @include relative-font-size(2.2);
    margin: 60px 0 19px;

    @include media-query($on-laptop) {
      @include relative-font-size(1.9);
    }
  }

  h3 {
    @include relative-font-size(1.8);
    margin: 60px 0 19px;

    @include media-query($on-laptop) {
      @include relative-font-size(1.5);
    }
  }

  h4 {
    @include relative-font-size(1.4);
    margin: 60px 0 19px;

    @include media-query($on-laptop) {
      @include relative-font-size(1.2);
    }
  }

  h5 {
    @include relative-font-size(1.1);
    margin: 60px 0 19px;

    @include media-query($on-laptop) {
      @include relative-font-size(1.0);
    }
  }

  h6 {
    @include relative-font-size(0.9);
    margin: 60px 0 19px;

    @include media-query($on-laptop) {
      @include relative-font-size(0.8);
    }
  }

  /* ---------- Media ---------- */
  img,
  svg,
  iframe {
    margin-left: auto;
    margin-right: auto;
  }

  img:not(.emoji),
  svg,
  iframe {
    display: block;
    max-height: 50vh;
  }

  /* ---------- Paragraph & Horizontal rule ---------- */

  hr {
    height: 1px;
    background-color: #ebebeb;
    border: none;
    margin: 60px 0;
  }

    img, svg, iframe {
      margin-left: auto;
      margin-right: auto;
    }

    img:not(.emoji), svg, iframe {
      display: block;
      max-height: 50vh;
    }

  }

  .post-related {
    &>*:first-child {
      @include relative-font-size(1.425);
      color: #3E3F40;
      margin-bottom: 14px;
    }

    ul {
      margin-left: 15px;
    }

    .post-link {
      @include relative-font-size(1.075);
      color: #3E3F40;

      &:hover {
        color: darken(#3E3F40, 50%);
      }
    }
  }
}

.post-comments {
  padding-top: 25px;
}

/**
 * Posts misc
 */
.post-nav {
  display: flex;
  justify-content: space-between;
  margin: 72px 0 59px;
  padding: 31px 0 0;
  gap: 36px;

  a {
    @include relative-font-size(1.125);
    color: #3E3F40;
    max-width: 45%;
    display: flex;
    align-items: center;

    * {
        overflow: hidden;
        text-wrap-mode: nowrap;
        text-overflow: ellipsis;
    }
  }

  .previous:before {
    content: ' ';
    border: solid #787878;
    border-width: 0 2px 2px 0;
    display: inline-block;
    padding: 4px;
    margin-right: 8px;
    transform: rotate(135deg);
    -webkit-transform: rotate(135deg);
  }

  .next:after {
    content: ' ';
    border: solid #787878;
    border-width: 0 2px 2px 0;
    display: inline-block;
    padding: 4px;
    margin-left: 8px;
    transform: rotate(-45deg);
    -webkit-transform: rotate(-45deg);
  }
}


/**
 * Archives page
 */
.page-archives {
  .page-archives-list {
    margin-left: 0;
    list-style: none;
  }

  .archives-time {
    @include relative-font-size(1.5);

    &:not(:first-child) {
      margin-top: 18px;
    }
    margin-bottom: 8px;
  }

  .post-meta {
    font-size: $small-font-size;
    color: $grey-color;
  }
}


/**
 * Page banner
 */
.page-banner {
  display: block;
  position: relative;
  height: $banner-height;
  background-color: $banner-background;
  transition: height 0.2s;

  .page-banner-img {
    position: absolute;
    width: 100%;
    height: 100%;
    overflow: hidden;

    & > *:first-child {
      @include center-image;
      transition: 0.1s all ease-in-out;
    }

    & > video {
      width: 100vw;
      object-fit: cover;
    }

    & > img.img-placeholder {
      display: none;
    }
  }

  .wrapper {
    height: 100%;
  }

  .page-banner-inner {
    @include vertical-center(relative);

    color: $banner-text-color;
    padding: 10px 5px;
    text-shadow: 1px 1px 2px #33333355;

    & > *:first-child {
      margin: 0;

      > :nth-child(1) {
        @include relative-font-size(3.9);
        letter-spacing: -1px;
        margin-bottom: 0.1em;
        font-weight: normal;
        transition: 0.2s all;

        @include media-query($on-palm) {
          @include relative-font-size(1.975);
        }
      }

      > :nth-child(2) {
        font-weight: lighter;
        margin-bottom: 0.8em;
        transition: 0.2s all;

        @include media-query($on-palm) {
          @include relative-font-size(1.175);
        }
      }

      > :last-child {
        margin-bottom: 0;
      }
    }

    .post-subtitle {
      @include relative-font-size(1.525);
      color: #ffffffcc;
      padding-right: 280px;

      @include media-query($on-palm) {
        padding-right: 0;
      }
    }

    .post-meta {
      color: #ffffffcc;
      padding-bottom: 1em;
    }

    .left-vsplit:before {
      background: #e3e3e388;
    }

    .post-tags {
      color: #999;
      padding-right: 280px;

      @include media-query($on-palm) {
        padding-right: 0;
      }

      .post-tag {
        @include relative-font-size(1.125);
        display: inline-block;
        text-decoration: none;
        margin: 9px 12px 0 0;
        color: #fff;

        &:hover {
          text-decoration: underline;
        }
      }
    }
  }

  @include media-query($on-palm) {
    height: divide($banner-height, 1.5);
  }
}


/**
 * Layout and sidebar
 */
.framework {
    @extend %flex;

  .main {
    @extend %flex-1;
  }

  .sidebar {
    padding-left: 8px;
    transition: top 0.2s, display 0.2s;

    @include flex-sticky($header-height + 20px);

    @include media-query($on-laptop) {
      display: none;
    }

  }
}


/**
 * Segments page
 */
.page-segments {
  .page-segments-list {
    margin-left: 0;
    list-style: none;
  }

  .segment-name {
    font-weight: $base-font-weight * 1.5;
    margin-bottom: 8px;
    position: relative;

    @include relative-font-size(1.6);

    &:not(:first-child) {
      margin-top: 28px;
    }

    &:hover:before {
      content: '#';
      left: -1em;
      position: absolute;
    }
  }

  .post-meta {
    font-size: $small-font-size;
    color: $grey-color;
  }

  li a {
    &.post-link {
      margin-left: 5px;
    }

    color: #303030;

    &:hover {
      color: #000;
    }
  }
}

.left-vsplit:before {
  content: "";
  display: inline-block;
  width: 1px;
  height: 10px;
  margin: 0 10px;
  background-color: #e3e3e3e3;
  vertical-align: baseline;
}

/**
 * Post badge
 */
.post-badges {
  display: inline-block;
  position: relative;
  margin-left: 8px;
  margin-top: 3px;
  user-select: none;
}

.pagination .post-badges {
  bottom: 0.5em;
}

.post-related .post-badges {
  bottom: 0.1em;
}

.page-segments .post-badges {
  bottom: 0.1em;
}

.post-badge {
  display: none;
  padding: 0px 3px;
  background-color: $brand-color;
  color: #fff;
  font-size: 10px;
  font-weight: 400;
  border-radius: 2px;
  transition-duration: $base-transition-duration;
}

.post-badge.badge-new {
  display: inline-block;
}

.top-post .post-badges .post-badge.badge-top {
  display: inline-block;
}

a:visited .post-badges .post-badge.badge-new {
  display: none;
  color: $background-color;
  background-color: $background-color;
}
