/* ─── 5. Typography: Body ───────────────────────────────────────────────── */
p,
li,
span,
figcaption {
  font-family: 'Inter', 'Helvetica Neue', Helvetica, Arial, 'Segoe UI',
    'Blix', 'IBM Plex Sans TC', 'PingFang TC', sans-serif;
  font-size: 1rem;
  line-height: 1.7;
  font-weight: 500;
}

p {
  margin-bottom: 1.4em;
}

blockquote {
  font-family: 'Inter', 'Helvetica Neue', Helvetica, Arial, sans-serif !important;
  font-size: 1rem !important;
  color: var(--black);
  background: none;
  border-left: none !important;
  padding: 0 0 0 2rem;
  margin: 2rem 0;
  letter-spacing: 0;
}

blockquote p,
blockquote li {
  font-family: 'Inter', 'Helvetica Neue', Helvetica, Arial, sans-serif !important;
  font-size: 1rem !important;
  color: var(--black) !important;
}

code,
pre {
  font-family: 'JetBrains Mono', 'Fira Mono', monospace !important;
  font-size: 0.8rem !important;
}

/* ─── 6. Typography: Headings ───────────────────────────────────────────── */
h1,
h2,
h3,
h4,
h5,
h6 {
  /* Inter for Latin; GenSekiGothicTW for CJK; Blix as CJK fallback */
  font-family: 'Inter', 'Helvetica Neue', Helvetica, Arial,
    'GenSekiGothicTW', 'Blix', 'PingFang TC', sans-serif !important;
  color: var(--black) !important;
  font-weight: 400;
  letter-spacing: -0.04em;
  line-height: 1.1;
}

h1 {
  font-size: 2.1rem;
}

h2 {
  font-size: 1.65rem;
}

h3 {
  font-size: 1.35rem;
}

h4 {
  font-size: 1.15rem;
}

h5 {
  font-size: 1.0rem;
}

h6 {
  font-size: 0.9rem;
}

/* Metadata labels: dates, categories, tags */
.post-meta,
time {
  font-size: 0.72rem;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  font-weight: 400;
}

/* ─── 7. Links ───────────────────────────────────────────────────────────── */
a {
  color: var(--black);
  text-decoration: none;
}

a:hover {
  color: var(--hover-text) !important;
  background-color: var(--hover-bg) !important;
  text-decoration: none !important;
}

/* Prevent inversion from bleeding into thumbnails */
a:hover img {
  background: transparent !important;
  filter: none;
}

/* ─── 8. Site header ────────────────────────────────────────────────────── */
html[data-header-transparent] header.site-header,
header.site-header {
  background: var(--white) !important;
  box-shadow: none !important;
  border-bottom: none !important;
}

html[data-header-transparent] header.site-header {
  position: sticky !important;
  top: 0;
  transition: top 0.3s ease;
  z-index: 1000;
}

html[data-scroll-status='down'] header.site-header {
  top: -64px;
}

html[data-scroll-status='up'],
html[data-scroll-status='top'] header.site-header {
  top: 0;
}

html[data-header-transparent] header.site-header .site-brand-inner,
html[data-header-transparent] header.site-header .page-link {
  color: var(--black);
}

.site-header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  position: relative;
}

/* Hide the small favicon/logo in the navbar */
.site-favicon {
  display: none !important;
}

/* Brand / site title: regular weight, compact */
.site-brand .site-brand-inner {
  font-family: 'Inter', 'Helvetica Neue', Helvetica, Arial,
    'Blix', 'PingFang TC', sans-serif;
  font-size: 1.0rem;
  font-weight: 400;
  letter-spacing: 0;
  color: var(--black);
}

.site-brand .site-brand-inner:hover,
.site-brand .site-brand-inner:visited:hover {
  color: var(--hover-text) !important;
  background-color: var(--hover-bg) !important;
}

/* Hide Jekyll's built-in checkbox nav — we use the hamburger */
.page-link,
label[for="nav-trigger"],
.menu-icon {
  display: none !important;
}

.site-nav {
  font-size: 0.85rem;
  line-height: 63.84px;
  position: absolute;
  right: 0;
  top: 0;
}

/* ─── 9. Search toggle ───────────────────────────────────────────────────── */
.search-toggle {
  background: none;
  border: none;
  cursor: pointer;
  margin-right: 60px;
  display: flex;
  align-items: center;
  height: 40px;
  color: var(--black);
}

.search-toggle:hover {
  color: var(--hover-text) !important;
  background-color: var(--hover-bg) !important;
}

/* ─── 10. Hamburger menu ─────────────────────────────────────────────────── */
.menu-toggle {
  width: 30px;
  height: 22px;
  cursor: pointer;
  z-index: 1001;
  display: block;
  position: absolute;
  top: 18px;
  right: 20px;

  span {
    display: block;
    height: 2px;
    background: var(--black);
    margin: 6px 0;
  }

  &.open span:nth-child(1) {
    transform: rotate(45deg) translate(5px, 5px);
  }

  &.open span:nth-child(2) {
    opacity: 0;
  }

  &.open span:nth-child(3) {
    transform: rotate(-45deg) translate(6px, -6px);
  }
}

.menu-wrapper {
  max-height: 0;
  opacity: 0;
  overflow: hidden;
  background: var(--white);
  border: 1px solid var(--black);
  position: absolute;
  top: 60px;
  right: 0;
  width: 160px;
  max-width: 90vw;
  z-index: 1000;
  display: flex;
  justify-content: flex-start;

  ul {
    display: flex;
    flex-direction: column;
    list-style: none;
    padding: 0.5rem 0;
    margin: 0;
    width: 100%;

    li {
      margin: 0;

      a {
        font-family: 'Inter', 'Helvetica Neue', Helvetica, Arial, sans-serif;
        font-size: 1rem;
        font-weight: 700;
        color: var(--black);
        text-decoration: none;
        padding: 0.5rem 1rem;
        display: block;
        text-align: left;

        &:hover {
          color: var(--hover-text) !important;
          background-color: var(--hover-bg) !important;
        }
      }
    }
  }

  &.open {
    max-height: 400px;
    opacity: 1;
  }
}

/* ─── 11. Page layout & wrapper ─────────────────────────────────────────── */
.page-content {
  padding: 0 !important;
}

.wrapper {
  max-width: 1000px;
  margin: auto;
  padding-left: 2rem;
  padding-right: 2rem;
}

/* ─── 12. Post list (homepage / articles) ───────────────────────────────── */
.pagination {

  .post-list {
    margin-left: 0;
    list-style: none;

    >li {
      background: transparent !important;
      padding: 4rem 0;
      margin-bottom: 0;
      border: none !important;
      border-bottom: none !important;

      &:hover {
        transform: none !important;
        border: none !important;
        background: transparent !important;
      }
    }

    /* Remove the nth-child separator set in _layout.scss */
    >li:not(:last-child) {
      border-bottom: none !important;
    }
  }

  .post-title {
    margin-bottom: 0.4rem;

    a {
      text-decoration: none;
    }
  }

  .post-link {
    font-family: 'Inter', 'Helvetica Neue', Helvetica, Arial, sans-serif !important;
    font-size: 1.2rem !important;
    font-weight: 400 !important;
    letter-spacing: -0.03em;
    color: var(--black) !important;
  }

  .post-meta {
    font-size: 0.72rem !important;
    text-transform: uppercase;
    letter-spacing: 0.06em;
    color: var(--black) !important;
    opacity: 0.45;
    margin-bottom: 0.6rem;
  }

  .post-text {
    color: var(--black) !important;
    font-size: 0.85rem;
  }

  .post-tags .post-tag {
    border: none !important;
    font-size: 0.72rem !important;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    color: var(--black) !important;
    padding: 0;
    margin-right: 0.75rem;

    &:hover {
      color: var(--hover-text) !important;
      background-color: var(--hover-bg) !important;
    }
  }

  .paginator {
    padding: 2rem 0 4rem;
    text-align: left;

    .previous,
    .next {
      font-weight: 700;
      font-size: 0.85rem;
      color: var(--black);

      &:hover {
        color: var(--hover-text) !important;
        background-color: var(--hover-bg) !important;
      }
    }

    .previous span,
    .next span {
      color: rgba(17, 17, 17, 0.3);
    }

    /* Remove CSS-border chevrons — keep them but strip the visual border */
    &>.previous:before,
    &>.next:after {
      border-color: rgba(17, 17, 17, 0.4) !important;
    }

    .indicator {
      padding: 0 1rem;
      font-size: 0.8rem;
      opacity: 0.45;
    }
  }
}

/* ─── 13. Single post ───────────────────────────────────────────────────── */
.post {

  .post-header {
    max-width: 760px;
    margin: 4rem auto 2rem;
    padding: 0 0 2rem;
    border: none !important;

    .post-title {
      font-size: 2rem !important;
      letter-spacing: -0.04em;
      line-height: 1.1 !important;
      margin-bottom: 0.75rem;
      font-weight: 400;
    }

    .post-subtitle {
      font-size: 1rem !important;
      font-weight: 400;
      color: var(--black);
      opacity: 0.55;
      margin-bottom: 0.4rem;
    }

    .post-meta {
      font-size: 0.72rem !important;
      text-transform: uppercase;
      letter-spacing: 0.06em;
      color: var(--black) !important;
      opacity: 0.45;
      padding-bottom: 0;
    }

    .post-tags {
      padding-right: 0;

      .post-tag {
        border: none !important;
        font-size: 0.72rem !important;
        text-transform: uppercase;
        letter-spacing: 0.05em;
        color: var(--black);
        margin-right: 0.75rem;

        &:hover {
          color: var(--hover-text) !important;
          background-color: var(--hover-bg) !important;
        }
      }
    }
  }
}

/* Constrain article width */
.post-content,
.post-header {
  max-width: 760px;
  margin-left: auto;
  margin-right: auto;
}

.post-content {
  margin-bottom: 0;

  h1 {
    font-size: 1.8rem !important;
    letter-spacing: -0.04em;
    line-height: 1.1 !important;
