    text-transform: uppercase;
    letter-spacing: 0.06em;
    font-weight: 700;
    color: var(--black) !important;
    opacity: 0.45;
    margin-bottom: 0.75rem;
  }

  .post-link {
    font-size: 1rem !important;
    color: var(--black) !important;

    &:hover {
      color: var(--hover-text) !important;
      background-color: var(--hover-bg) !important;
    }
  }
}

/* ─── 14. Post navigation (prev / next) ─────────────────────────────────── */
/* Override both the theme's .post-nav AND the custom classes from old design */
.post-nav {
  display: flex;
  justify-content: space-between;
  max-width: 760px;
  margin: 4rem auto;
  padding-top: 0;
  border-top: none !important;
  gap: 2rem;

  a {
    font-family: 'Inter', 'Helvetica Neue', Helvetica, Arial, sans-serif;
    font-size: 0.85rem;
    color: var(--black) !important;
    font-weight: 400;
    max-width: 45%;
    display: flex;
    align-items: center;

    &:hover {
      color: var(--hover-text) !important;
      background-color: var(--hover-bg) !important;
    }

    * {
      overflow: hidden;
      text-wrap-mode: nowrap;
      text-overflow: ellipsis;
    }
  }

  /* Replace CSS-border arrows with text characters */
  .previous:before {
    content: '←';
    border: none !important;
    margin-right: 0.5rem;
    padding: 0;
  }

  .next:after {
    content: '→';
    border: none !important;
    margin-left: 0.5rem;
    padding: 0;
  }
}

/* Old custom post-nav class variants */
.post-nav-item {
  width: 48%;
}

.post-nav-next {
  text-align: right;
}

.post-nav-link {
  display: block;
  padding: 0;
  border: none !important;
  background: transparent !important;
  color: var(--black);

  &:hover {
    background-color: transparent !important;
  }
}

.post-nav-title {
  font-size: 0.85rem;
  font-weight: 700;
  margin-top: 0.25rem;
