/* ─── 15. Page banner ───────────────────────────────────────────────────── */
.page-banner {
  background-image: none !important;
  background-color: var(--white) !important;
}

.page-banner-inner {
  text-shadow: none !important;

  .left-vsplit:before {
    background: transparent;
  }

  .post-subtitle,
  .post-meta {
    color: rgba(17, 17, 17, 0.55) !important;
  }

  .post-tags .post-tag {
    color: var(--black) !important;
    border: none !important;
  }
