  border: none !important;
  background: none !important;
  padding: 0 !important;
  margin: 0 !important;
  text-align: left;
  text-shadow: none !important;
}

.page-banner-heading::before,
.page-banner-heading::after,
.page-banner-subheading::before,
.page-banner-subheading::after {
  content: none !important;
  border: none !important;
}

/* ─── 16. Site footer ───────────────────────────────────────────────────── */
.site-footer {
  background-color: var(--white) !important;
  color: var(--black) !important;
  border: none !important;
  font-size: 0.75rem;

  .site-footer-inner {
    border-top: none !important;
    padding: 4rem 0 2rem;
  }

  a {
    color: var(--black);

    &:hover {
      color: var(--hover-text) !important;
      background-color: var(--hover-bg) !important;
    }
  }
}

/* ─── 17. Tables ────────────────────────────────────────────────────────── */
table {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.8rem;
  margin-bottom: 2rem;
  color: var(--black) !important;

  tr:nth-child(even) {
    background-color: transparent !important;
  }

  th,
  td {
    border: 1px solid rgba(17, 17, 17, 0.15) !important;
    padding: 0.5rem 0.75rem;
    background: transparent !important;
    text-align: left;
    font-size: 0.8rem;
    color: var(--black);
  }

  th {
    font-weight: 700;
    border-color: rgba(17, 17, 17, 0.35) !important;
    background: transparent !important;
  }
}

/* Explicit simple-table class (used in posts) */
table.simple-table {

  th,
  td {
    border: 1px solid rgba(17, 17, 17, 0.15);
    padding: 0.5rem 0.75rem;
    background: transparent;
  }

  th {
    font-weight: 700;
    border-color: rgba(17, 17, 17, 0.35);
    background: transparent !important;
  }

  tbody tr:hover>td,
  tbody tr:hover>th {
    background: rgba(17, 17, 17, 0.03) !important;
  }
}

/* ─── 18. Search overlay ────────────────────────────────────────────────── */
.search-overlay {
  position: fixed;
  inset: 0;
  z-index: 9999;
  display: flex;
  justify-content: center;
  align-items: flex-start;
  padding: 10vh 2rem;
  background: rgba(255, 255, 255, 0.95);
  backdrop-filter: none;
  -webkit-backdrop-filter: none;
}

.search-overlay.hidden {
  display: none;
}

.search-panel {
  position: relative;
  width: var(--search-width);
  padding: 1.25rem 1.25rem 0;
  background: var(--white);
  border: 1px solid var(--black);
}

.search-header {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  padding-right: 0;
}

.search-header #search-input {
  flex: 1;
  font-size: var(--search-input-font);
  padding: 1rem 1.25rem;
  min-height: 52px;
  line-height: 1.35;
}

#search-input[type="search"]::-webkit-search-cancel-button,
#search-input[type="search"]::-webkit-search-decoration {
  -webkit-appearance: none;
  appearance: none;
  display: none;
}

#search-input[type="search"]::-ms-clear {
  display: none;
  width: 0;
  height: 0;
}

#search-input {
  background: transparent;
  border: none;
  outline: none;
  padding: 0.9rem 1.1rem;
  color: var(--black);
  font-family: 'Inter', 'Helvetica Neue', Helvetica, Arial, sans-serif;
}

#search-results {
  max-height: 70vh;
  overflow: auto;
  margin-top: 0.75rem;
}

.search-item {
  border-top: none !important;
  padding: 1rem 1.25rem;

  &:hover {
    background: var(--hover-bg) !important;

    * {
      color: var(--hover-text) !important;
    }
  }
}

#search-close {
  position: static !important;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 42px;
  min-height: 42px;
  padding: 0.4rem 0.65rem;
  font-size: 20px;
  background: transparent;
  border: none;
  cursor: pointer;
  opacity: 0.7;
  color: var(--black);

  &:hover {
    opacity: 1;
    background: var(--hover-bg) !important;
    color: var(--hover-text) !important;
  }
}

.search-title {
  font-weight: 700;
  font-size: var(--search-title-font);
  color: var(--black);
}

.search-snippet {
  margin-top: 0.35rem;
  font-size: var(--search-snippet-font);
  opacity: 0.8;
  color: var(--black);
}

mark {
  background: rgba(0, 0, 255, 0.12);
  padding: 0 0.1em;
}

/* ─── 19. Header inline search form ─────────────────────────────────────── */
.header-search-form {
  opacity: 0;
  pointer-events: none;
  transform: translateY(-10px);
  transition: opacity 0.2s, transform 0.2s;
  position: absolute;
  top: 60px;
  right: 24px;
  z-index: 1000;
  background: var(--white);
  border: 1px solid var(--black);
  padding: 0.5rem 1rem;

  &.show {
    opacity: 1;
    pointer-events: auto;
    transform: translateY(0);
  }

  input {
    font-family: 'Inter', 'Helvetica Neue', Helvetica, Arial, sans-serif;
    font-size: 0.85rem;
    padding: 0.25rem 0.5rem;
    border: none;
    background: transparent;
    color: var(--black);
    outline: none;
    width: 160px;
  }
}

/* ─── 20. Archives ──────────────────────────────────────────────────────── */
.page-archives {
  .page-archives-list {
    margin-left: 0;
    list-style: none;
  }

  .archives-time {
    font-size: 0.72rem !important;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    font-weight: 700;
    margin-top: 3rem;
    margin-bottom: 0.75rem;
  }

  .post-meta {
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    opacity: 0.45;
  }
}

/* ─── 21. Segments (categories / tags pages) ─────────────────────────────── */
.page-segments {
  .page-segments-list {
    margin-left: 0;
    list-style: none;
  }

  .segment-name {
    font-size: 0.72rem !important;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    font-weight: 700;
    margin-top: 3rem;
    margin-bottom: 0.75rem;

    /* Remove '#' hover pseudo-element */
    &:hover:before {
      content: none;
    }
  }

  .post-meta {
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    opacity: 0.45;
  }

  li a {
    color: var(--black);
    font-size: 0.85rem;

    &:hover {
      color: var(--hover-text) !important;
      background-color: var(--hover-bg) !important;
    }

    &.post-link {
      margin-left: 0.5rem;
    }
  }
}

/* ─── 22. Vertical split separator — remove ─────────────────────────────── */
.left-vsplit:before {
  display: none;
}

/* ─── 23. Post badges ───────────────────────────────────────────────────── */
.post-badge {
  background-color: var(--black) !important;
  color: var(--white) !important;
  font-size: 0.55rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  padding: 0 3px;
}

/* ─── 24. Dark mode — keep pure white regardless of OS preference ────────── */
@media (prefers-color-scheme: dark) {
  :root {
    --white: #FFFFFF;
    --black: #111111;
  }

  html,
  body,
  .page-content,
  .site-header,
  .site-footer {
    background-color: #FFFFFF !important;
    color: #111111 !important;
  }
}

html[data-theme="dark"] {
  --white: #FFFFFF;
  --black: #111111;
}

html[data-theme="dark"],
html[data-theme="dark"] body,
html[data-theme="dark"] .page-content,
html[data-theme="dark"] .site-header,
html[data-theme="dark"] .site-footer {
  background-color: #FFFFFF !important;
  color: #111111 !important;
}

/* ─── 25. Responsive: tablet (≤ 800px) ──────────────────────────────────── */
@media screen and (max-width: 800px) {
  .wrapper {
    padding-left: 1.5rem;
    padding-right: 1.5rem;
  }

  .pagination .post-list>li {
    padding: 2.5rem 0;
  }

  .post .post-header {
    margin: 2.5rem auto 1.5rem;
  }

  .post-nav {
    flex-direction: column;
    gap: 1.5rem;
    margin: 3rem auto;
  }

  .post-nav-item,
  .post-nav a {
    width: 100% !important;
    max-width: 100% !important;
  }

  .post-nav-next {
    text-align: left;
  }
}

/* ─── 26. Responsive: mobile (≤ 480px) ──────────────────────────────────── */
@media screen and (max-width: 480px) {
  .wrapper {
    padding-left: 1rem;
    padding-right: 1rem;
  }

  .pagination .post-list>li {
    padding: 2rem 0;
  }

  .search-panel {
    width: min(94vw, 720px);
  }

  .search-header #search-input {
    min-height: 48px;
  }

  h1.page-banner-heading,
  h2.page-banner-heading,
  h3.page-banner-heading,
  h4.page-banner-heading,
  h5.page-banner-heading,
  h6.page-banner-heading,
  h1.page-banner-subheading,
  h2.page-banner-subheading,
  h3.page-banner-subheading,
  h4.page-banner-subheading,
  h5.page-banner-subheading,
  h6.page-banner-subheading {
    font-size: 1.5rem !important;
  }
}

/* ─── 27. Responsive: banner headings (≤ 768px) ─────────────────────────── */
@media screen and (max-width: 768px) {

  h1.page-banner-heading,
  h2.page-banner-heading,
  h3.page-banner-heading,
  h4.page-banner-heading,
  h5.page-banner-heading,
  h6.page-banner-heading,
  h1.page-banner-subheading,
  h2.page-banner-subheading,
  h3.page-banner-subheading,
  h4.page-banner-subheading,
  h5.page-banner-subheading,
  h6.page-banner-subheading {
    font-size: 1.75rem !important;
  }
}

/* ═══════════════════════════════════════════════════════════════════════════
   28. MAGAZINE LAYOUT — Swiss/Brutalist editorial grid
   ═══════════════════════════════════════════════════════════════════════════ */

/* — Narrow wrapper: tight left/right margins, full-bleed feel — */
.wrapper {
  max-width: 1400px;
  padding-left: 2rem;
  padding-right: 2rem;
}

/* — Header: thin bottom rule, no bg, no shadow — */
.site-header {
  border-bottom: 1.5px solid var(--black) !important;
  padding-top: 0.6rem;
  padding-bottom: 0.6rem;
}

/* — Brand: uppercase mono-style label — */
.site-brand .site-brand-inner {
  font-size: 1rem !important;
  font-weight: 700 !important;
  text-transform: uppercase !important;
  letter-spacing: 0.12em !important;
}

/* — Desktop nav: inline layout — */
@media screen and (min-width: 801px) {
  /* Hamburger: hide */
  .menu-toggle {
    display: none !important;
  }

  /* Pull old .site-nav out of absolute positioning into flex flow */
  .site-nav {
    position: static !important;
    line-height: 1 !important;
    display: flex !important;
    align-items: center !important;
    margin-left: auto; /* push nav + search to the right */
    font-size: 0 !important; /* collapse the checkbox whitespace */
  }

  /* Show trigger items inline */
  .site-nav .trigger {
    display: flex !important;
    align-items: center !important;
  }

  label[for="nav-trigger"],
  .menu-icon {
    display: none !important;
  }

  .site-nav .trigger .page-link {
    display: inline-flex !important;
    align-items: center !important;
    font-size: 1rem !important;
    font-weight: 700 !important;
    text-transform: uppercase !important;
    letter-spacing: 0.1em !important;
    padding: 0.3rem 0.75rem !important;
    color: var(--black) !important;
    text-decoration: none !important;
    white-space: nowrap !important;

    &:hover {
      color: var(--hover-text) !important;
      background-color: var(--hover-bg) !important;
    }
  }

  /* Search toggle: no right-margin gap for hamburger */
  .search-toggle {
    margin-right: 0 !important;
  }
}

/* — Hide banner entirely on homepage (no heading set) — */
.page-banner:not(:has(h1, h2, h3, h4, h5, h6)) {
  display: none !important;
}

/* — Hide sidebar on list/pagination pages — */
.framework:has(.pagination) .sidebar {
  display: none !important;
}

/* — Post list header row — */
.post-list-header {
  display: grid;
  grid-template-columns: 2.5rem 6rem 1fr auto;
  grid-template-areas: "num date title tags";
  align-items: baseline;
  padding: 0.4rem 0;
  border-top: 1.5px solid var(--black);
  border-bottom: 1px solid var(--black);
  margin-bottom: 0;
  font-size: 0.62rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--black);
  opacity: 0.5;

  .col-num   { grid-area: num; }
  .col-date  { grid-area: date; }
  .col-title { grid-area: title; }
  .col-tags  { grid-area: tags; text-align: right; padding-right: 0.5rem; }
}

/* — Post list: reset default card style — */
.pagination .post-list {
  list-style: none;
  margin: 0;
  padding: 0;
  counter-reset: post-counter;

  > li.post-item,
  > li.top-post {
    counter-increment: post-counter;
    display: grid;
    grid-template-columns: 2.5rem 6rem 1fr auto;
    grid-template-areas: "num date title tags";
    align-items: baseline;
    padding: 0.75rem 0;
    border-bottom: 1px solid rgba(17, 17, 17, 0.12);
    gap: 0;
    margin: 0;

    /* Remove old card padding/background */
    background: transparent !important;
    box-shadow: none !important;

    /* Counter number */
    &::before {
      content: counter(post-counter, decimal-leading-zero);
      grid-area: num;
      font-size: 0.65rem;
      font-weight: 700;
      color: var(--black);
      opacity: 0.35;
      align-self: center;
    }

    /* Hide everything we don't want */
    .post-excerpt,
    .post-author,
    .post-reading-time,
    .post-image,
    .post-text,
    .left-vsplit,
    .fa,
    .fa-solid,
    .fa-regular {
      display: none !important;
    }

    /* Date — grid area */
    .post-date {
      grid-area: date;
      font-size: 0.7rem;
      font-weight: 400;
      color: var(--black);
      opacity: 0.5;
      letter-spacing: 0;
      align-self: center;
    }

    /* Title link — grid area */
    .post-title {
      grid-area: title;
      margin: 0;
      padding: 0;
      align-self: center;

      .post-link {
        font-size: 0.95rem;
        font-weight: 500;
        color: var(--black);
        text-decoration: none;
        letter-spacing: -0.01em;
        line-height: 1.3;
        display: block;
        padding: 0.1rem 0.5rem;

        &:hover {
          color: var(--hover-text) !important;
          background-color: var(--hover-bg) !important;
        }
      }
    }

    /* Tags — grid area */
    .post-tags {
      grid-area: tags;
      display: flex;
      gap: 0.35rem;
      align-items: center;
      justify-content: flex-end;
      padding-right: 0.25rem;

      .post-tag {
        font-size: 0.58rem;
        font-weight: 700;
        text-transform: uppercase;
        letter-spacing: 0.07em;
        padding: 0.1rem 0.4rem;
        color: var(--black);
        background: transparent;
        border: 1px solid var(--black);
        text-decoration: none;

        &:hover {
          color: var(--hover-text) !important;
          background-color: var(--hover-bg) !important;
          border-color: var(--hover-text) !important;
        }
      }
    }

    /* Post meta wrapper — flatten */
    .post-meta {
      display: contents;
    }
  }

  /* Pin badge on top post */
  > li.top-post .post-badge {
    display: inline-block !important;
  }
}

/* — Paginator links — */
.paginator {
  margin-top: 2rem;
  font-size: 0.7rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;

  a {
    color: var(--black);
    padding: 0.2rem 0.5rem;
    text-decoration: none;

    &:hover {
      color: var(--hover-text) !important;
      background-color: var(--hover-bg) !important;
    }
  }
}

/* — Mobile (≤ 640px): collapse to 2-column — */
@media screen and (max-width: 640px) {
  .wrapper {
    padding-left: 1rem;
    padding-right: 1rem;
  }

  .post-list-header {
    grid-template-columns: 2.5rem 1fr;
    grid-template-areas: "num title";

    .col-date,
    .col-tags {
      display: none;
    }
  }

  .pagination .post-list > li.post-item,
  .pagination .post-list > li.top-post {
    grid-template-columns: 2.5rem 1fr;
    grid-template-areas:
      "num title"
      ".   tags";

    .post-date {
      display: none;
    }

    .post-tags {
      justify-content: flex-start;
      padding-left: 0;
    }
  }
}

/* ─── 29. Google Translate widget — brutalist reset ─────────────────────── */

/* Trigger button */
.ct-language {
  background-color: transparent !important;
  border-radius: 0 !important;
  padding: 0.3rem 0.75rem !important;

  &:before {
    font-size: 0.68rem;
    font-family: 'Inter', 'Helvetica Neue', Helvetica, Arial, sans-serif;
    content: "TR \25BE" !important; /* plain text label + small arrow */
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    color: var(--black);
    font-family: inherit !important;
  }

  &:hover {
    background-color: var(--hover-bg) !important;

    &:before {
      color: var(--hover-text);
    }
  }
}

/* Dropdown panel */
.ct-language-dropdown {
  border-radius: 0 !important;
  transition: none !important;
  -webkit-transition: none !important;
  box-shadow: none !important;
  -webkit-box-shadow: none !important;
  background-color: var(--white) !important;
  border: 1px solid var(--black) !important;
  width: 110px !important;
  right: 0 !important;
  top: 100% !important;

  li {
    padding: 0 !important;
    border-bottom: none !important;

    &:first-child { padding-top: 0 !important; }
    &:last-child  { padding-bottom: 0 !important; }

    a {
      display: flex !important;
      align-items: center !important;
      gap: 0.4rem !important;
      padding: 0.35rem 0.6rem !important;
      font-size: 0.68rem !important;
      font-weight: 700 !important;
      text-transform: uppercase !important;
      letter-spacing: 0.08em !important;
      color: var(--black) !important;
      text-decoration: none !important;

      img {
        width: 16px !important;
        height: auto !important;
        flex-shrink: 0 !important;
      }

      &:hover {
        background-color: var(--hover-bg) !important;
        color: var(--hover-text) !important;
      }
    }
  }
}

/* Show on hover (instant) */
.ct-language:hover .ct-language-dropdown {
  max-height: 10000px !important;
  visibility: visible !important;
  margin-top: 0 !important;
}

.ct-language-selected {
  background-color: transparent !important;
}
